# Round 32 / Phase 2.D: spawn the Admin Console (port 5152) inside
# the main app's process as a daemon thread so the bundled .app
# actually serves http://127.0.0.1:5152/.  Build6 hidden-imported
# enhanced_admin_dashboard_v2 for its helper functions but never
# started the server, so the Admin Console was unreachable from a
# packaged install.  Idempotent (guarded by ``sys._adoptiq_admin_started``)
# and skips entirely under pytest so test fixtures don't try to bind
# the port.  Failures (port in use, import error, generic exception)
# log and return -- they MUST NOT block the main app from starting.
def _start_admin_server_in_thread() -> None:
    """Start enhanced_admin_dashboard_v2.admin_app on a daemon thread."""
    import threading

    if os.environ.get("PYTEST_CURRENT_TEST"):
        return
    if getattr(sys, "_adoptiq_admin_started", False):
        return

    # Round 37 / Phase 1: pin ADOPTIQ_MAIN_URL to the live main-app
    # port BEFORE importing the admin module.  The packaged .app
    # runs the main UI on 15152 (and admin on 5152), but the admin
    # module historically defaulted to localhost:5151 when the env
    # was unset.  That made the admin's "Server Status" tile probe
    # the wrong port, miss, decide running=False, and render the
    # "Start Server" button while the server was right there.  The
    # parent process owns the port; the admin reads it.  Defense in
    # depth: enhanced_admin_dashboard_v2._main_app_host_port now
    # also re-reads this env per call so a later rebind picks up.
    try:
        _main_port = _resolve_main_port()
    except Exception:  # noqa: BLE001 - never block admin start
        _main_port = None
    if _main_port:
        os.environ["ADOPTIQ_MAIN_URL"] = f"http://127.0.0.1:{_main_port}"

    try:
        from enhanced_admin_dashboard_v2 import admin_app, _resolve_admin_port
    except Exception as _imp_err:  # noqa: BLE001 - never block main app
        logging.getLogger(__name__).warning(
            "Round 32 / Phase 2.D: admin module unavailable; admin console will not auto-start (%s)",
            _imp_err,
        )
        return

    # Round 34 / H1: enforce the loopback default unless the operator
    # has explicitly opted into a public bind via
    # ``ADOPTIQ_ADMIN_BIND_PUBLIC=1``.  Pre-Round-34 the helper read
    # ``ADOPTIQ_ADMIN_HOST`` directly, which let an operator (or a
    # misconfigured deployment) set ``ADOPTIQ_ADMIN_HOST=0.0.0.0``
    # WITHOUT setting the public-bind safety gate.  Net: the admin
    # console silently bound to every interface.  CLAUDE.md is
    # explicit: "Don't change [the loopback] default without the
    # ADOPTIQ_ADMIN_BIND_PUBLIC=1 escape hatch."  Mirror the
    # standalone __main__ path in enhanced_admin_dashboard_v2.py
    # (lines 3922-3946) which already enforces this contract.
    _admin_loopback_hosts = {"127.0.0.1", "::1", "localhost"}
    _admin_bind_public = str(os.environ.get("ADOPTIQ_ADMIN_BIND_PUBLIC", "")).strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }
    host = (os.environ.get("ADOPTIQ_ADMIN_HOST") or "127.0.0.1").strip()
    if not host:
        host = "127.0.0.1"
    if host not in _admin_loopback_hosts and not _admin_bind_public:
        # Operator tried to bind the admin console to a non-loopback
        # interface without flipping the safety gate.  Refuse and
        # fall back to loopback with a WARN so the operator sees the
        # downgrade rather than discovering it months later from a
        # security scan.
        logging.getLogger(__name__).warning(
            "Round 34 / H1: ignoring ADOPTIQ_ADMIN_HOST=%r because "
            "ADOPTIQ_ADMIN_BIND_PUBLIC is not set; binding admin "
            "console to 127.0.0.1.  Set ADOPTIQ_ADMIN_BIND_PUBLIC=1 "
            "to opt into a public bind.",
            host,
        )
        host = "127.0.0.1"
    port = _resolve_admin_port()

    _admin_logger = logging.getLogger(__name__)

    def _run() -> None:
        try:
            admin_app.run(host=host, port=port, debug=False, use_reloader=False, threaded=True)
        except OSError as e:
            _admin_logger.warning(
                "Round 32 / Phase 2.D: admin port %s unavailable (likely a "
                "second AdoptIQ instance or an external admin process is "
                "already bound); skipping in-process admin: %s",
                port,
                e,
            )
        except Exception:  # noqa: BLE001 - daemon thread; log and exit
            _admin_logger.exception(
                "Round 32 / Phase 2.D: admin console crashed in background thread; main app continuing"
            )

    t = threading.Thread(target=_run, name="adoptiq-admin", daemon=True)
    t.start()
    sys._adoptiq_admin_started = True
    _admin_logger.info(
        "Round 32 / Phase 2.D: admin console launched in background thread on http://%s:%s/",
        host,
        port,
    )


def auto_audit_report(analysis_id: str):
    """Automatically trigger audit after report completion"""
    if not AUDIT_ENABLED:
        return

    # Round 8 / Phase 1.9: ``analysis_id`` embeds customer / manager /
    # technology fragments, so previous logger.info / logger.error lines
    # leaked PII to shipped log files.  Compute a SHA-256 short digest
    # locally (this function runs before ``_id_digest`` is defined further
    # down in module load order) and surface only the digest at INFO /
    # ERROR; verbatim id is available at DEBUG only.
    try:
        import hashlib as _h_p19

        _aid_digest = _h_p19.sha256(str(analysis_id).encode("utf-8", errors="replace")).hexdigest()[:12]
    except Exception:
        _aid_digest = "unavailable"

    try:
        # Run audit in background thread to not block completion
        def run_audit():
            try:
                result = trigger_audit(analysis_id)
                logger.info(
                    "Auto-audit completed aid_digest=%s status=%s score=%s/100",
                    _aid_digest,
                    result.get("status"),
                    result.get("score"),
                )
                logger.debug("Auto-audit verbatim id=%s status=%s", analysis_id, result.get("status"))
            except Exception as e:
                logger.error("Auto-audit failed aid_digest=%s err_kind=%s", _aid_digest, type(e).__name__)
                logger.debug("Auto-audit failure verbatim id=%s", analysis_id, exc_info=True)

        audit_thread = threading.Thread(target=run_audit, daemon=True)
        audit_thread.start()
    except Exception as e:
        logger.error("Failed to trigger auto-audit aid_digest=%s err_kind=%s", _aid_digest, type(e).__name__)
        logger.debug("Auto-audit trigger failure verbatim id=%s", analysis_id, exc_info=True)


class AnalysisForm(FlaskForm):
    """Form for analysis configuration"""

    report_type = RadioField(
        "Report Type",
        choices=[
            ("comprehensive", "Comprehensive"),
            ("compact", "Compact"),
            ("renewal", "Customer Renewal"),
            ("renewal_portfolio", "Portfolio Renewal"),
        ],
        default="comprehensive",
        validators=[DataRequired()],
    )

    manager = SelectField(
        "Manager",
        choices=[],  # Will be set dynamically from team_config.json
        validators=[DataRequired()],
    )

    technology = SelectField(
        "Technology",
        choices=[
            ("Webex Meetings & Messaging", "Webex Meetings & Messaging"),
            ("Webex Calling", "Webex Calling"),
            ("Webex Contact Center", "Webex Contact Center"),
            ("Webex Contact Center Enterprise", "Webex Contact Center Enterprise"),
            ("Cisco UCCE", "Cisco UCCE"),
            ("Cisco UCCX", "Cisco UCCX"),
            ("All Contact Center", "All Contact Center"),
            ("All", "All"),
        ],
        validators=[DataRequired()],
    )

    customer_name = StringField("Customer Name", validators=[OptionalValidator()])

    days = IntegerField("Analysis Period (days)", default=90, validators=[DataRequired(), NumberRange(min=1, max=365)])

    csone_file = FileField("CSOne Excel File (Optional)", validators=[OptionalValidator()])

    submit_btn = SubmitField("Generate Report")


