# Round 74 / Phase 1 (F1): same lazy-import problem applies to the
# post-save footer enforcer.  ``_r74_enforce_footer_safe`` (below) lazy-
# imports ``_r74_footer_enforcer`` inside its try/except, so PyInstaller
# never sees the dependency without an explicit pin.  Without this pin
# the frozen build silently skips post-save footer enforcement and the
# Build 47 P0 (empty footers across all 4 reports) reappears the moment
# any writer call site bypasses ``apply_word_footer``.
import _r74_footer_enforcer as _r74_footer_enforcer_pyinstaller_pin  # noqa: F401


def _r57_inject_citations_safe(docx_path: Optional[str], scenario_key: str) -> None:
    """Best-effort wrapper around ``inject_source_citations_into_docx``.

    Round 57 / Phase B contract: the injector NEVER breaks the report
    finalization path.  If the path is missing, the file does not
    exist, or the underlying call raises, we log and move on -- the
    user still gets the report; the worst case is the quality gate
    stays red for that one scenario, never that the report itself
    fails to ship.
    """
    if not docx_path:
        return
    try:
        path = Path(str(docx_path))
        if not path.exists():
            return
        counts = _r57_inject_source_citations(path, scenario_key=scenario_key)
        logger.info(
            "[R57] inject_source_citations(%s): paragraphs=%d cells=%d "
            "captions=%d skipped_cited=%d skipped_no_numeric=%d errors=%d",
            scenario_key,
            counts.get("paragraphs_injected", 0),
            counts.get("table_cells_injected", 0),
            counts.get("table_captions_added", 0),  # Round 114 / Build 83
            counts.get("skipped_already_cited", 0),
            counts.get("skipped_no_numeric", 0),
            counts.get("errors", 0),
        )
    except Exception as inj_err:
        logger.warning(
            "[R57] inject_source_citations(%s) failed for %s: %s",
            scenario_key,
            docx_path,
            inj_err,
        )


def _r74_enforce_footer_safe(docx_path: Optional[str], scenario_key: str) -> None:
    """Defense-in-depth wrapper around ``enforce_build_label_footer``.

    Round 74 / Phase 1 (F1): Build 47 acceptance confirmed all 4 DOCX
    artifacts ship with empty footers despite the R73/F1 in-memory
    hardening of ``_r68_build_label.apply_word_footer``.  Some upstream
    writer call site is bypassing the wrapped ``.save()`` and the
    rendered footer never carries the build label.

    This wrapper runs AFTER the report file is on disk and operates on
    the .docx zip bytes directly -- no upstream writer can prevent the
    label from landing.  When enforcement actually had to inject
    (i.e. the writer DID bypass ``apply_word_footer``) we log at WARNING
    with the writer hint so a future deeper investigation can identify
    which call site is responsible.

    Contract: NEVER raises -- a failure logs at warning and returns so
    the user still gets the report, even if the build label is missing
    in the worst case.
    """
    if not docx_path:
        return
    try:
        from _r74_footer_enforcer import enforce_build_label_footer  # noqa: PLC0415

        diag = enforce_build_label_footer(docx_path)
        injected = bool(diag.get("injected"))
        reason = str(diag.get("reason", ""))
        if injected:
            logger.warning(
                "[R74] footer enforced post-save for %s (writer bypassed apply_word_footer); docx=%s parts=%s",
                scenario_key,
                os.path.basename(str(docx_path)),
                diag.get("footer_parts_replaced"),
            )
        elif reason == "already stamped":
            logger.debug(
                "[R74] footer already stamped for %s; docx=%s",
                scenario_key,
                os.path.basename(str(docx_path)),
            )
        else:
            logger.warning(
                "[R74] footer enforcement skipped for %s: %s; docx=%s",
                scenario_key,
                reason,
                os.path.basename(str(docx_path)),
            )
    except Exception as enf_err:  # noqa: BLE001
        logger.warning(
            "[R74] footer enforcer failed for %s: %s; docx=%s",
            scenario_key,
            enf_err,
            docx_path,
        )


def validate_manager_input(manager: str) -> tuple[bool, str]:
    """Validate manager input"""
    if not manager or not isinstance(manager, str):
        return False, "Manager is required"

    if len(manager) > 100:
        return False, "Manager name too long"

    # Check for SQL injection attempts
    dangerous_chars = ["'", '"', ";", "--", "/*", "*/", "xp_", "sp_"]
    if any(char in manager.lower() for char in dangerous_chars):
        return False, "Invalid characters in manager name"

    return True, "Valid"


def validate_technology_input(technology: str) -> tuple[bool, str]:
    """Validate technology input"""
    if not technology or not isinstance(technology, str):
        return False, "Technology is required"

    if len(technology) > 100:
        return False, "Technology name too long"

    # Check for SQL injection attempts
    dangerous_chars = ["'", '"', ";", "--", "/*", "*/", "xp_", "sp_"]
    if any(char in technology.lower() for char in dangerous_chars):
        return False, "Invalid characters in technology name"

    return True, "Valid"


def validate_days_input(days: int) -> tuple[bool, str]:
    """Validate days input"""
    if not isinstance(days, int):
        return False, "Days must be a number"

    if days < 1 or days > 365:
        return False, "Days must be between 1 and 365"

    return True, "Valid"


def _ensure_inline_source_claim(text: Any, metric_name: str = "Derived Metric", fields: List[str] = None) -> str:
    claim = str(text or "").strip()
    if not claim:
        return ""
    if re.search(r"\[\s*source\s*:", claim, flags=re.IGNORECASE):
        return claim
    return f"{claim} {format_inline_source(metric_name, fields=fields or [])}"


def _normalized_account_ids(df: pd.DataFrame) -> List[str]:
    if df is None or df.empty or "ACCOUNT_ID_C" not in df.columns:
        return []
    values = df["ACCOUNT_ID_C"].dropna().astype(str).str.strip()
    values = values[(values != "") & (values.str.lower() != "none")]
    return sorted(set(values.tolist()))


def _normalize_account_id_for_parity(value: Any) -> str:
    token = str(value or "").strip().upper()
    if not token or token in {"NONE", "NAN", "NULL"}:
        return ""
    return token


def _account_tokens_for_parity(values: List[Any]) -> tuple[set[str], set[str]]:
    exact: set[str] = set()
    sf15: set[str] = set()
    for value in values or []:
        token = _normalize_account_id_for_parity(value)
        if not token:
            continue
        exact.add(token)
        if len(token) >= 15:
            sf15.add(token[:15])
    return exact, sf15


def _log_customer_pulse_parity(team_subs_df: pd.DataFrame, pulse_df: pd.DataFrame, scope_label: str) -> None:
    if pulse_df is None or pulse_df.empty:
        logger.info(f"[[PULSE_PARITY]] {scope_label}: no customer pulse rows returned")
        return
    expected_ids_raw = _normalized_account_ids(team_subs_df)
    expected_exact, expected_sf15 = _account_tokens_for_parity(expected_ids_raw)
    pulse_acct_col = next((c for c in ACCOUNT_COLUMN_CANDIDATES if c in pulse_df.columns), None)
    if not pulse_acct_col:
        logger.warning(f"[[PULSE_PARITY]] {scope_label}: pulse data missing account ID column")
        return
    backfill_mask = pd.Series([False] * len(pulse_df), index=pulse_df.index)
    if "PULSE_BACKFILL" in pulse_df.columns:
        backfill_mask = (
            pulse_df["PULSE_BACKFILL"].fillna("").astype(str).str.strip().str.lower().isin({"1", "true", "yes", "on"})
        )

    in_window_df = pulse_df[~backfill_mask]
    backfill_df = pulse_df[backfill_mask]

    observed_total_exact, observed_total_sf15 = _account_tokens_for_parity(
        pulse_df[pulse_acct_col].dropna().astype(str).tolist()
    )
    observed_window_exact, observed_window_sf15 = _account_tokens_for_parity(
        in_window_df[pulse_acct_col].dropna().astype(str).tolist()
    )
    observed_backfill_exact, observed_backfill_sf15 = _account_tokens_for_parity(
        backfill_df[pulse_acct_col].dropna().astype(str).tolist()
    )

    matched_window_exact = expected_exact & observed_window_exact
    matched_window_sf15 = {
        token
        for token in (expected_exact - matched_window_exact)
        if len(token) >= 15 and token[:15] in observed_window_sf15
    }
    matched_window_total = matched_window_exact | matched_window_sf15

    remaining_after_window = expected_exact - matched_window_total
    matched_backfill_exact = remaining_after_window & observed_backfill_exact
    matched_backfill_sf15 = {
        token
        for token in (remaining_after_window - matched_backfill_exact)
        if len(token) >= 15 and token[:15] in observed_backfill_sf15
    }
    matched_backfill_total = matched_backfill_exact | matched_backfill_sf15
    matched_total = matched_window_total | matched_backfill_total

    in_window_coverage = (len(matched_window_total) / len(expected_exact)) if expected_exact else 1.0
    total_coverage = (len(matched_total) / len(expected_exact)) if expected_exact else 1.0
    missing_expected = sorted(expected_exact - matched_total)
    unexpected_observed = sorted(
        token
        for token in observed_total_exact
        if token not in expected_exact and (len(token) < 15 or token[:15] not in expected_sf15)
    )
    logger.info(
        "[[PULSE_PARITY]] %s: expected_accounts=%d observed_accounts=%d in_window_matched=%d backfill_matched=%d total_matched=%d in_window_coverage=%.2f total_coverage=%.2f (sf15_matches=%d)",
        scope_label,
        len(expected_exact),
        len(observed_total_exact),
        len(matched_window_total),
        len(matched_backfill_total),
        len(matched_total),
        in_window_coverage,
        total_coverage,
        len(matched_window_sf15) + len(matched_backfill_sf15),
    )
    if total_coverage < 0.5:
        logger.warning(
            "[[PULSE_PARITY]] %s: low pulse-account total coverage %.2f (in_window=%.2f); missing_expected_sample=%s unexpected_observed_sample=%s",
            scope_label,
            total_coverage,
            in_window_coverage,
            missing_expected[:5],
            unexpected_observed[:5],
        )
    elif in_window_coverage < 0.5 and len(matched_backfill_total) > 0:
        logger.warning(
            "[[PULSE_PARITY]] %s: in-window pulse coverage %.2f is low but backfill increased total coverage to %.2f; review data freshness before treating as true recent sentiment",
            scope_label,
            in_window_coverage,
            total_coverage,
        )


def _apply_subtech_scope_fallback(ab_df: pd.DataFrame, technology: str) -> pd.DataFrame:
    if ab_df is None or ab_df.empty or "sub_technology" not in ab_df.columns:
        return ab_df
    canonical = str(technology or "").strip()
    if canonical == "Contact Center":
        canonical = "All Contact Center"
    allowed = {
        "All Contact Center",
        "Webex Contact Center",
        "Webex Contact Center Enterprise",
        "Cisco UCCE",
        "Cisco UCCX",
    }
    if canonical not in allowed:
        return ab_df
    normalized = ab_df.copy()
    unknown_mask = (
        normalized["sub_technology"]
        .fillna("")
        .astype(str)
        .str.contains(r"^unknown$|other/unknown", case=False, regex=True)
    )
    if unknown_mask.any():
        normalized.loc[unknown_mask, "sub_technology"] = canonical
    return normalized


app = Flask(
    __name__,
    template_folder=str(_BASE_PATH / "templates"),
    static_folder=str(_BASE_PATH / "static"),
)
# Use environment key in packaged builds; generate dev-only ephemeral key in source mode.
_env_secret_key = os.environ.get("ADOPTIQ_SECRET_KEY")
if _env_secret_key:
    app.config["SECRET_KEY"] = _env_secret_key
elif _frozen:
    raise RuntimeError("ADOPTIQ_SECRET_KEY must be set for packaged builds.")
else:
    app.config["SECRET_KEY"] = secrets.token_urlsafe(48)
app.config["UPLOAD_FOLDER"] = str(_APP_SUPPORT / "uploads")
_max_file_size_mb = int(os.environ.get("MAX_FILE_SIZE", "50"))
app.config["MAX_CONTENT_LENGTH"] = _max_file_size_mb * 1024 * 1024
# Round 8 / Phase 1.11: single env-driven cap for intel export/import sizes.
# Previously ``import_intel`` enforced a hard-coded 50 MB while
# ``MAX_CONTENT_LENGTH`` (above) was already configurable via
# ``MAX_FILE_SIZE`` -- two limits in two places drifted apart and made
# the smaller of the two effectively silent.  Anchor on the same env
# var so operators only have one knob to tune.
INTEL_MAX_BYTES = _max_file_size_mb * 1024 * 1024

# CSRF protection - enabled with extended timeout to prevent timeout issues
app.config["WTF_CSRF_ENABLED"] = True
app.config["WTF_CSRF_TIME_LIMIT"] = None  # No timeout limit for CSRF tokens
app.jinja_env.globals["csrf_token"] = generate_csrf

# Round 12 / Phase 4.4 + 4.5: ``format_number`` is the canonical
# integer/decimal renderer used by the Word/Excel exports
# (``report_utils.format_number``).  Several Jinja templates (most
# notably ``external_intelligence.html`` and ``history.html``) were
# rendering totals via raw ``{{ value }}`` so the same metric appeared
# as ``1234`` in HTML but ``1,234`` in Word/Excel, and a 100k+ count
# rendered without any thousands separator at all -- both an accuracy
# regression vs the canonical surface and a readability regression
# (e.g. "1234567 cases").  Register the helper as a Jinja filter so
# templates can pipe through ``{{ value | format_number }}`` and stay
# in lock-step with the export-side formatter.  Falls back to a safe
# inline implementation if ``report_utils`` cannot be imported during
# bootstrap (e.g. unit-test contexts that import this module without
# the full dependency tree).
try:
    from report_utils import format_number as _r12_jinja_format_number  # type: ignore
except Exception:  # pragma: no cover - defensive for partial test imports

    def _r12_jinja_format_number(value, decimals=0, percent=False):  # type: ignore
        try:
            if value is None or value == "":
                return "N/A"
            v = float(value)
            if percent:
                return f"{v:,.{decimals}f}%"
            if decimals:
                return f"{v:,.{decimals}f}"
            return f"{int(round(v)):,}"
        except (TypeError, ValueError):
            return str(value)


app.jinja_env.filters["format_number"] = _r12_jinja_format_number

# Round 5 / Phase 2.15: explicitly set Flask session cookie attributes so
# we never rely on framework defaults that vary across Flask releases.
# - HttpOnly: blocks JS access to the cookie (defense-in-depth vs XSS).
# - SameSite=Lax: blocks cross-site requests from carrying the cookie
#   while still permitting top-level navigations (form posts from the
#   same origin work; embedded cross-origin requests do not).
# - Secure: only set when the deployment is HTTPS (controlled via
#   ADOPTIQ_SECURE_COOKIES=1 or inferred from ADOPTIQ_MAIN_URL). The frozen
#   desktop app serves loopback HTTP, so frozen status alone must never add a
#   Secure cookie that the browser then refuses to return.
app.config.setdefault("SESSION_COOKIE_HTTPONLY", True)
app.config.setdefault("SESSION_COOKIE_SAMESITE", "Lax")
_secure_cookie_env = os.environ.get("ADOPTIQ_SECURE_COOKIES", "").strip().lower()
app.config["SESSION_COOKIE_SECURE"] = resolve_session_cookie_secure(
    _secure_cookie_env,
    os.environ.get("ADOPTIQ_MAIN_URL", "http://localhost:5151"),
)
# Mirror onto the CSRF cookie so Flask-WTF's double-submit token rides
# the same hardened transport.
app.config.setdefault("REMEMBER_COOKIE_HTTPONLY", True)
app.config.setdefault("REMEMBER_COOKIE_SAMESITE", "Lax")
app.config.setdefault("REMEMBER_COOKIE_SECURE", app.config["SESSION_COOKIE_SECURE"])

# Verbose debug mode can be enabled via env and changed at runtime through local admin APIs.
_VERBOSE_DEBUG_RUNTIME = None
_VERBOSE_DEBUG_LOCK = Lock()


def _is_truthy_flag(value: Any) -> bool:
    return str(value).strip().lower() in {"1", "true", "yes", "on"}


def _empty_df_with_fetch_marker(dataset: str, error: str) -> pd.DataFrame:
    """
    Phase 1.3a helper: return an empty DataFrame whose ``.attrs`` carry the
    dataset name and failure reason. Mirrors ``adoptiq_backend.
    _empty_df_with_fetch_error`` so app-level fetch wrappers (CSConsole
    threadpool, CSOne loader, etc.) emit the same signal.
    """
    df = pd.DataFrame()
    try:
        df.attrs["fetch_error"] = str(error or "").strip() or "unknown_error"
        df.attrs["fetch_error_dataset"] = dataset
    except Exception:
        # Round 4: non-fatal; suppressed silently in original code
        pass  # noqa: PIE790
    return df


def _empty_df_preserving_source_attrs(source: Any) -> pd.DataFrame:
    """Return an empty scoped frame without erasing source availability state."""

    if not isinstance(source, pd.DataFrame):
        return pd.DataFrame()
    result = source.iloc[0:0].copy()
    result.attrs.update(dict(getattr(source, "attrs", {}) or {}))
    return result


def _is_verbose_debug_enabled() -> bool:
    if _VERBOSE_DEBUG_RUNTIME is not None:
        return bool(_VERBOSE_DEBUG_RUNTIME)
    return _is_truthy_flag(os.environ.get("ADOPTIQ_VERBOSE_DEBUG", "0"))


def _apply_verbose_debug_mode() -> bool:
    enabled = _is_verbose_debug_enabled()
    level = logging.DEBUG if enabled else logging.INFO
    logging.getLogger().setLevel(level)
    return enabled


def _set_verbose_debug_mode(enabled: bool, source: str = "runtime") -> bool:
    global _VERBOSE_DEBUG_RUNTIME
    with _VERBOSE_DEBUG_LOCK:
        _VERBOSE_DEBUG_RUNTIME = bool(enabled)
        os.environ["ADOPTIQ_VERBOSE_DEBUG"] = "1" if enabled else "0"
        active = _apply_verbose_debug_mode()
    logging.getLogger(__name__).info("Verbose debug mode %s via %s", "enabled" if active else "disabled", source)
    return active


