@app.route("/api/version", methods=["GET"])
def api_version():
    """Round 68 / Build 42 (A2): expose the running binary's identity.

    Build 41 acceptance shipped reports from a pre-Build-41 binary because
    the operator copied the new ``.app`` into ``/Applications`` but did not
    quit and re-launch the running process.  This endpoint surfaces the
    information needed to spot that condition without opening a report:

    * ``version`` / ``build``       -- ``ADOPTIQ_VERSION`` / ``ADOPTIQ_BUILD``
    * ``process_started_at_utc``    -- captured at app boot via _r68_build_label
    * ``code_loaded_at_utc``        -- mtime of ``app_simple.py`` on disk
    * ``dmg_install_at_utc``        -- mtime of ``sys.executable`` (frozen only)
    * ``restart_required``          -- ``True`` when ``dmg_install_at_utc`` is
      strictly after ``process_started_at_utc`` (i.e. a newer .app is
      installed but not active)

    Loopback safe -- echoes no secret material, no PII.  ``base.html``
    polls this once per session and renders a non-dismissable banner when
    ``restart_required=True`` so the operator cannot miss the trap.
    """
    try:
        from _r68_build_label import (  # noqa: PLC0415
            _resolve_code_loaded_at_utc,
            _resolve_dmg_install_at_utc,
            _resolve_version_build,
            get_process_started_at_utc,
        )

        version, build = _resolve_version_build()
        process_started = get_process_started_at_utc()
        code_loaded = _resolve_code_loaded_at_utc()
        dmg_install = _resolve_dmg_install_at_utc()

        # Round 68 / A2: ``restart_required`` is the headline signal.  A
        # truthy value means "a newer .app is installed than the one
        # currently running" -- the operator must quit and re-launch
        # before generating new reports.  We only flag this when both
        # timestamps are present AND the install is strictly newer
        # (avoids false positives from clock drift / equal mtimes).
        restart_required = False
        try:
            if dmg_install and process_started and dmg_install > process_started:
                restart_required = True
        except Exception:  # noqa: BLE001
            restart_required = False

        return jsonify(
            {
                "ok": True,
                "version": version,
                "build": build,
                "process_started_at_utc": process_started,
                "code_loaded_at_utc": code_loaded,
                "dmg_install_at_utc": dmg_install,
                "restart_required": restart_required,
                "frozen": bool(getattr(sys, "frozen", False)),
            }
        ), 200
    except Exception as e:
        logger.error("Round 68 / A2: /api/version failed: %s", e, exc_info=True)
        return jsonify({"ok": False, "error_kind": "version_endpoint_error"}), 500


@app.route("/api/diag/dsm-columns", methods=["GET"])
def api_diag_dsm_columns():
    """Round 82 / Phase A1 -- enumerate columns on the DSM assignment table.

    Exists so an operator can identify the exact secondary-CSSM column
    name in their Snowflake environment without opening a separate
    Snowflake session.  The conservative ``_R82_SECONDARY_DSM_EMAIL_CANDIDATES``
    tuple in ``adoptiq_backend`` covers the common naming patterns
    (``SECONDARY_DSM_EMAIL``, ``BACKUP_DSM_EMAIL``, ``OWNER_EMAIL_2``,
    ``DELEGATE_DSM_EMAIL``, etc.); this endpoint surfaces ANY column
    in the table that ends in ``_EMAIL`` / ``_EMAIL_2`` /
    ``_EMAIL_BACKUP`` so a missing pattern can be spotted and added
    in a follow-on commit.

    Auth: same dual-path as ``/api/corpus/refresh`` -- a Flask-WTF
    CSRF token (browser path) OR a constant-time-compared
    ``X-AdoptIQ-Internal`` header (admin-app proxy path).  Loopback-only
    by default since the main app binds to 127.0.0.1 unless
    ``ADOPTIQ_BIND_PUBLIC=1`` is set.

    Response shape::

        {
            "ok": true,
            "table": "CX_DB.CX_SWSSBST_BR.dsm_assignment_data",
            "columns": [...],
            "primary_email_columns_present": [...],
            "secondary_email_candidates_present": [...],
            "all_email_like_columns": [...],
            "introspected_at": "<UTC ISO-8601>",
            "error_kind": null
        }

    Returns HTTP 200 on success, 403 on auth failure, 503 on
    Snowflake-unreachable, 500 on harness failure.  No PII; only
    schema metadata.
    """
    authorized = False
    _internal_expected = os.environ.get("ADOPTIQ_INTERNAL_TOKEN", "")
    _internal_provided = request.headers.get("X-AdoptIQ-Internal", "")
    if (
        _internal_expected
        and _internal_provided
        and secrets.compare_digest(str(_internal_expected), str(_internal_provided))
    ):
        authorized = True

    if not authorized and app.config.get("WTF_CSRF_ENABLED", True):
        try:
            validate_csrf(
                request.headers.get("X-CSRFToken")
                or request.headers.get("X-CSRF-Token")
                or request.form.get("csrf_token")
                or request.args.get("csrf_token")
            )
            authorized = True
        except Exception:
            authorized = False
    elif not authorized and not app.config.get("WTF_CSRF_ENABLED", True):
        authorized = True

    if not authorized:
        return jsonify({"ok": False, "error": "CSRF validation failed"}), 403

    ctx = None
    try:
        from adoptiq_backend import _connect_with_keeper as _r82_connect
        from adoptiq_backend import introspect_dsm_columns as _r82_introspect

        ctx = _r82_connect()
        payload = _r82_introspect(ctx)
        status_code = 200 if payload.get("ok") else 503
        return jsonify(payload), status_code
    except Exception as err:
        logger.error(
            "Round 82 / api_diag_dsm_columns harness failed: %s",
            type(err).__name__,
            exc_info=True,
        )
        return jsonify(
            {
                "ok": False,
                "error": "DSM column-discovery diagnostic failed",
                "error_kind": "diag.dsm_columns.unhandled",
            }
        ), 500
    finally:
        if ctx is not None:
            try:
                ctx.close()
            except Exception:
                pass


@app.route("/api/diag/connectivity", methods=["GET"])
def api_diag_connectivity():
    """Run the DNS -> TLS -> AppRole -> secret-read -> Snowflake self-test.

    Round 5 hotfix: lets users (and support) see *which* stage of the Keeper /
    Snowflake chain is actually failing instead of the old blanket "Please
    ensure you are connected to the Cisco VPN" banner. Returns JSON; never
    echoes secret material.
    """
    try:
        from connectivity_diagnostics import run_connectivity_diagnostics

        secrets: Dict[str, str] = {}
        try:
            from _bundled_secrets import get_secrets as _get_bundled_secrets

            secrets.update(_get_bundled_secrets() or {})
        except Exception as _bs_err:
            logger.debug("No bundled secrets for diag: %s", _bs_err)

        for key in (
            "KEEPER_URL",
            "KEEPER_NAMESPACE",
            "KEEPER_ROLE_ID",
            "KEEPER_SECRET_ID",
            "KEEPER_SECRET_PATH",
            "SNOWFLAKE_USER",
            "SNOWFLAKE_ACCOUNT",
            "SNOWFLAKE_ROLE",
            "SNOWFLAKE_WAREHOUSE",
        ):
            env_val = os.environ.get(key)
            if env_val:
                secrets[key] = env_val

        result = run_connectivity_diagnostics(secrets)
        status_code = 200 if result.get("ok") else 503
        return jsonify(result), status_code
    except Exception as e:
        # Round 8 / Phase 1.2: previously the response payload included
        # ``detail = f'{type(e).__name__}: {e}'[:240]`` which leaked driver
        # exception text (paths, hostnames, library tracebacks) to whoever
        # could reach the endpoint.  Match the Round 7 / Phase 3.14 pattern:
        # generic ``error_kind`` for the client, full traceback only in the
        # operator-facing log.
        logger.error("Connectivity diagnostics endpoint failed: %s", e, exc_info=True)
        return jsonify(
            {
                "ok": False,
                "error": "Connectivity diagnostics harness itself failed",
                "error_kind": "diag.harness.unhandled",
            }
        ), 500


_R142_ARTIFACT_SUFFIX_RE = re.compile(
    r"(?:_\d{8}_\d{6}Z?)?\.(?:docx|xlsx)$",
    re.IGNORECASE,
)


def _r142_report_group_id(filename: object) -> str:
    """Return one grouping key for a Word report and either workbook name."""
    # Round 142: the new Source_Data prefix and legacy Data prefix must pair
    # with the same Report stem in Previous Reports.  Match longer prefixes
    # before the generic AdoptIQ_ fallback.
    report_id = _R142_ARTIFACT_SUFFIX_RE.sub("", str(filename or ""))
    if report_id.startswith("Leader_Report_"):
        return "Leader_" + report_id[len("Leader_Report_") :]
    for prefix in (
        "AdoptIQ_Source_Data_",
        "AdoptIQ_Report_",
        "AdoptIQ_Data_",
        "AdoptIQ_",
    ):
        if report_id.startswith(prefix):
            return report_id[len(prefix) :]
    return report_id


@app.route("/previous-reports")
def previous_reports():
    """Browse and download previous reports from the output folder"""
    try:
        import os
        import glob
        from datetime import datetime, timedelta
        import re

        # Get all Word and Excel files from outputs directory (canonical when frozen)
        outputs_dir = str(_r92_report_outputs_root(create=True))  # Round 92
        if not os.path.exists(outputs_dir):
            os.makedirs(outputs_dir)

        # Find all report files (including leader reports - both old and new naming).
        # Round 81 / Build 57: switch from top-level ``glob.glob`` to
        # ``Path.rglob`` so the new ``<Manager>/<Type>/`` nested layout
        # is walked.  ``rglob`` returns ``Path`` objects so we cast to
        # ``str`` for back-compat with downstream string-only sorting.
        _r81_outputs_path = Path(outputs_dir)
        word_files = [str(p) for p in _r81_outputs_path.rglob("AdoptIQ_*.docx")] + [
            str(p) for p in _r81_outputs_path.rglob("Leader_Report_*.docx")
        ]
        # Source Data workbooks are the evidence artifact exposed beside a
        # report.  Historical ``AdoptIQ_Report_*.xlsx`` files are retained on
        # disk for compatibility, but they are summary workbooks and must not
        # replace or appear as the canonical Source Data download in this UI.
        excel_files = [
            str(p)
            for p in _r81_outputs_path.rglob("AdoptIQ_*.xlsx")
            if not p.name.casefold().startswith("adoptiq_report_")
        ]

        # Round 13 / Phase 10.8 + 11.8: previously this consumed
        # ``glob.glob(...)`` results in raw filesystem order, which
        # varies by OS / FS readdir order (e.g. macOS APFS returns
        # alphabetic, ext4 returns insertion order, NTFS returns
        # hash-bucket order).  The downstream group dict therefore
        # got a non-deterministic insertion ordering, and the final
        # ``modified`` field for each group could disagree on which
        # of two same-mtime files won.  Sort both lists by mtime
        # descending (newest first) with a stable lexicographic
        # tie-break on the file path so identical timestamps still
        # produce a reproducible iteration order across hosts.
        def _r13_mtime_key(_path: str) -> tuple:
            try:
                _mt = os.stat(_path).st_mtime
            except Exception:
                _mt = 0.0
            return (-float(_mt or 0.0), str(_path))

        try:
            word_files = sorted(word_files, key=_r13_mtime_key)
            excel_files = sorted(excel_files, key=_r13_mtime_key)
        except Exception:
            pass

        # Group files by report (remove file extension and timestamp to group them)
        report_groups = {}

        # Process Word files
        for file_path in word_files:
            try:
                stat = os.stat(file_path)
                filename = os.path.basename(file_path)

                # Extract report identifier (remove .docx and timestamp)
                # Pattern: AdoptIQ_Report_Manager_Technology_Days_YYYYMMDD_HHMMSS.docx
                # Pattern: AdoptIQ_Report_Compact_Manager_Technology_Days_YYYYMMDD_HHMMSS.docx
                # Pattern: AdoptIQ_Report_Renewal_Customer_Technology_Days_YYYYMMDD_HHMMSS.docx
                # Pattern: AdoptIQ_Report_Leader_Manager_Days_YYYYMMDD_HHMMSS.docx
                # Pattern: Leader_Report_Manager_Days_YYYYMMDD_HHMMSS.docx (legacy)
                report_id = _r142_report_group_id(filename)

                if report_id not in report_groups:
                    report_groups[report_id] = {
                        "word_file": None,
                        "excel_file": None,
                        "modified": None,
                        "total_size": 0,
                    }

                # The candidate list is newest-first with a stable path
                # tie-break. Keep the first Word artifact for the group so an
                # older retained copy cannot overwrite it later in the loop.
                if report_groups[report_id]["word_file"] is None:
                    report_groups[report_id]["word_file"] = {
                        "name": filename,
                        "path": file_path,
                        "size": stat.st_size,
                        "modified": datetime.fromtimestamp(stat.st_mtime),
                    }

            except Exception as e:
                logger.warning(f"Could not get file info for {file_path}: {e}")

        # Process Excel files
        for file_path in excel_files:
            try:
                stat = os.stat(file_path)
                filename = os.path.basename(file_path)

                # Extract report identifier (remove .xlsx and timestamp)
                # Pattern: AdoptIQ_Report_Manager_Technology_Days_YYYYMMDD_HHMMSS.xlsx
                # Pattern: AdoptIQ_Source_Data_Manager_Technology_Days_YYYYMMDD_HHMMSS.xlsx
                # Legacy pattern: AdoptIQ_Data_Manager_Technology_Days_YYYYMMDD_HHMMSS.xlsx
                report_id = _r142_report_group_id(filename)

                if report_id not in report_groups:
                    report_groups[report_id] = {
                        "word_file": None,
                        "excel_file": None,
                        "modified": None,
                        "total_size": 0,
                    }

                folded_name = filename.casefold()
                if folded_name.startswith("adoptiq_report_"):
                    # Defense in depth in case discovery changes later.
                    continue
                if folded_name.startswith("adoptiq_source_data_"):
                    source_priority = 0
                elif folded_name.startswith("adoptiq_data_"):
                    source_priority = 1
                else:
                    source_priority = 2

                current_priority = report_groups[report_id].get("_excel_priority")
                # Prefer canonical Source Data regardless of legacy workbook
                # mtime. Within one naming tier, newest-first ordering means
                # the first candidate is the deterministic winner.
                if current_priority is None or source_priority < current_priority:
                    report_groups[report_id]["excel_file"] = {
                        "name": filename,
                        "path": file_path,
                        "size": stat.st_size,
                        "modified": datetime.fromtimestamp(stat.st_mtime),
                    }
                    report_groups[report_id]["_excel_priority"] = source_priority

            except Exception as e:
                logger.warning(f"Could not get file info for {file_path}: {e}")

        # Derive group metadata only from the two artifacts actually exposed.
        # Hidden retained workbooks must not affect displayed size or recency.
        for report_data in report_groups.values():
            report_data.pop("_excel_priority", None)
            selected_files = [
                artifact
                for artifact in (
                    report_data.get("word_file"),
                    report_data.get("excel_file"),
                )
                if artifact
            ]
            report_data["total_size"] = sum(int(artifact.get("size") or 0) for artifact in selected_files)
            report_data["modified"] = max(
                (artifact["modified"] for artifact in selected_files),
                default=None,
            )

        # Sort reports by modification time (newest first)
        # Round 11 / Phase 11.1: secondary tie-break on the
        # report_id key so two reports written within the same
        # filesystem mtime second (frequent on fast SSDs / signed
        # bundle deploys) get a deterministic, reproducible order
        # in the listing instead of relying on dict insertion
        # order.  Use ascending report_id within a tie so the
        # alphabetically first id wins, matching how the rest of
        # the app sorts deterministic ties.
        sorted_reports = sorted(
            report_groups.items(),
            key=lambda x: (
                # primary: newest mtime first => negate timestamp so
                # ascending sort matches reverse=True ordering
                -(x[1]["modified"].timestamp() if x[1].get("modified") else 0.0),
                # secondary: stable lexicographic on report_id
                str(x[0] or ""),
            ),
        )

        # Round 28 / Phase 2: hand off to templates/previous_reports.html
        # which extends base.html (dark-default + sun/moon toggle inherited
        # from the site-wide theme system).  The previous inline f-string
        # forced a hardcoded light palette and bypassed the toggle.  All
        # the data-collection logic above stays unchanged; we only
        # reshape ``sorted_reports`` so the template can iterate without
        # leaking ``os.path`` / ``datetime`` formatting concerns into
        # Jinja.
        _view_reports = []
        for report_id, report_data in sorted_reports:
            modified_dt = report_data.get("modified")
            modified_str = modified_dt.strftime("%Y-%m-%d %H:%M:%S") + " (local)" if modified_dt else "Unknown"
            total_size_bytes = report_data.get("total_size") or 0
            total_size_mb = f"{(total_size_bytes / 1024 / 1024):.1f}" if total_size_bytes > 0 else "0.0"
            word_file = report_data.get("word_file")
            excel_file = report_data.get("excel_file")
            _view_reports.append(
                (
                    report_id,
                    {
                        "readable_name": str(report_id).replace("_", " ").title(),
                        "modified_str": modified_str,
                        "total_size_mb": total_size_mb,
                        "word_file": ({"basename": os.path.basename(word_file["path"])} if word_file else None),
                        "excel_file": ({"basename": os.path.basename(excel_file["path"])} if excel_file else None),
                    },
                )
            )

        return render_template("previous_reports.html", sorted_reports=_view_reports)

    except Exception as e:
        logger.error(f"Error browsing previous reports: {e}")
        return "Error loading previous reports. Please try again.", 500


