@app.route("/start_leader_report", methods=["POST"])
def start_leader_report():
    """Start a leader report generation"""
    if app.config.get("WTF_CSRF_ENABLED", True):
        try:
            validate_csrf(
                request.headers.get("X-CSRFToken")
                or request.headers.get("X-CSRF-Token")
                or request.form.get("csrf_token")
            )
        except Exception:
            return jsonify(
                {"ok": False, "success": False, "error": "CSRF validation failed"}
            ), 403  # Round 13 / Phase 4.3
    try:
        manager = request.form.get("manager")
        # Round 142: ``scope_value`` is the canonical submitted value. For a
        # member report it is the roster email; for a customer report it is
        # the customer label. ``scope_member`` optionally narrows a customer
        # to one of the manager's direct reports.
        scope_type = str(request.form.get("scope_type", "team") or "team").strip().lower()
        scope_value = str(request.form.get("scope_value", "") or "").strip()
        scope_member = str(request.form.get("scope_member", "") or "").strip()
        try:
            days = int(request.form.get("days", 90))
        except (ValueError, TypeError):
            days = 90

        # Validate inputs
        is_valid_mgr, error_msg = validate_manager_input(manager)
        if not is_valid_mgr:
            return jsonify({"success": False, "error": error_msg}), 400

        is_valid_days, error_msg = validate_days_input(days)
        if not is_valid_days:
            return jsonify({"success": False, "error": error_msg}), 400

        try:
            scope_selection = validate_leader_scope_request(
                manager,
                scope_type,
                scope_value,
                TEAM_ROSTER,
                member_email=scope_member,
            )
        except LeaderScopeValidationError as scope_error:
            return jsonify({"success": False, "error": str(scope_error)}), 400

        # Use the roster's canonical manager spelling in status, output paths,
        # and all later filters. A crafted member from another manager is
        # rejected above before an upload is saved or a worker is started.
        manager = scope_selection.manager_name
        scope_type = scope_selection.scope_type
        scope_value = scope_selection.scope_value
        scope_member = scope_selection.member_email
        if scope_type == "customer":
            is_valid_customer, customer_error = validate_customer_name_input(scope_value)
            if not is_valid_customer:
                return jsonify({"success": False, "error": customer_error}), 400

        # Handle optional CSOne file upload.
        #
        # Round 38 / Phase 1: split the explicit-upload path from the
        # OneDrive-autodiscovery fallback so the worker's two-pass
        # validator can distinguish "operator clicked Upload and chose
        # this file" (treat csone as required, fail loud if empty)
        # from "no upload, but we found a file in the synced OneDrive
        # folder" (treat csone as optional, degrade gracefully if
        # empty).  Pre-Round-38 both code paths collapsed into one
        # ``csone_file`` variable, which let an autodiscovered file
        # masquerade as an explicit upload and short-circuit the
        # leader report with a "csone missing or empty" error before
        # the file was even loaded.
        csone_file_explicit: Optional[str] = None
        if "csone_file" in request.files:
            file = request.files["csone_file"]
            if file and file.filename:
                is_valid, error_msg = validate_file_upload(file)
                if not is_valid:
                    return jsonify({"success": False, "error": error_msg}), 400

                import uuid as _uuid

                raw_name = secure_filename(file.filename)
                filename = _r13_unique_upload_filename(_uuid, raw_name, file)
                filepath = os.path.join(app.config["UPLOAD_FOLDER"], filename)
                file.save(filepath)
                csone_file_explicit = filepath
        # When no explicit upload: try the most recent .xlsx from the
        # OneDrive folder (macro places reports daily).  This is a
        # convenience hop; it MUST NOT be promoted to a fail-loud
        # required source by the worker.
        csone_file_autopicked: Optional[str] = None
        # Round 68 / Build 42 (B1): capture the OneDrive sync status
        # so a present-but-empty / placeholder-only folder shows up
        # as a partial-data warning the operator sees in the report
        # banner instead of a silent fall-through to "no CSOne".
        _r68_csone_sync_status: str = "unknown"
        _r68_csone_sync_count: int = 0
        if not csone_file_explicit:
            csone_file_autopicked, _r68_csone_sync_status, _r68_csone_sync_count = get_latest_csone_from_folder_diag()

        # Resolved-effective path the worker actually loads.  Either
        # the explicit upload or the autodiscovered fallback (or
        # ``None`` if neither was found).
        csone_file = csone_file_explicit or csone_file_autopicked

        # Generate unique analysis ID. Round 142 adds the validated scope plus
        # a collision-resistant nonce: manager+days+second alone allowed two
        # simultaneous requests to overwrite each other's persisted scope.
        timestamp = int(time.time())
        analysis_id = (
            f"Leader_{_sanitize_analysis_id_part(manager)}_{days}d_{timestamp}_{scope_type}_{secrets.token_hex(4)}"
        )

        # Initialize status
        active_report_model = _r91_active_report_model_snapshot()  # Round 91
        with analysis_status_lock:
            analysis_status[analysis_id] = {
                "status": "starting",
                "progress": 0,
                "message": " Initializing Leader Report Generation...",
                "start_time": _now_utc_iso_z(),
                "current_step": "Initialization",
                "step_start_time": _now_utc_iso_z(),  # Round 91
                "active_report_model": active_report_model,  # Round 91
                "report_model_name": active_report_model,  # Round 91
                "phase_timings": {},  # Round 91
                "manager": manager,
                "days": days,
                "report_type": "leader",
                # Round 142: persist the server-canonical scope so the worker
                # never needs to trust request data or infer UI state.
                "scope_type": scope_type,
                "scope_value": scope_value,
                "scope_member": scope_member,
                "scope_display": scope_selection.display_value,
                # Back-compat: the worker still reads ``csone_file`` for
                # path resolution and several log lines downstream key
                # off this name.  We keep it pointing at the resolved-
                # effective path.
                "csone_file": csone_file,
                # Round 38 / Phase 1: explicit provenance flag the
                # worker reads to decide whether to fail loud on an
                # empty csone load (Pass 2 validation).  TRUE iff the
                # operator actively uploaded a file via the UI;
                # FALSE when only OneDrive autodiscovery returned a
                # path.
                "csone_file_was_uploaded": bool(csone_file_explicit),
                # Round 38 / Phase 1: canonical resolved-effective
                # path (mirrors ``csone_file`` above; named
                # explicitly so future code paths don't have to
                # reverse-engineer the legacy key).
                "csone_file_path": csone_file,
                "results": None,
                "error": None,
            }
            # Round 68 / Build 42 (B1): when the operator did NOT
            # upload a file AND OneDrive autodiscovery came back
            # ``not_synced`` (folder missing, unreadable, empty, or
            # all entries are 0-byte placeholders), record an
            # honest ``partial_data_warnings`` entry so the report
            # banner names the failure mode.  ``unknown`` (env not
            # set) is also recorded so the operator knows where to
            # remediate.  ``synced`` short-circuits silently.
            if not csone_file_explicit and _r68_csone_sync_status != "synced":
                _pdw = analysis_status[analysis_id].setdefault("partial_data_warnings", [])
                _pdw.append(
                    {
                        "dataset": "csone",
                        "kind": "no_onedrive_sync",
                        "sync_status": _r68_csone_sync_status,
                        "real_file_count": _r68_csone_sync_count,
                        "error": (
                            "OneDrive autodiscovery for CSOne returned no synced "
                            "data (status={status}). Upload a CSOne export "
                            "directly, or sync the configured folder via the "
                            "OneDrive desktop client."
                        ).format(status=_r68_csone_sync_status),
                    }
                )
            save_analysis_status()

        # Start leader report generation in background thread
        thread = threading.Thread(target=run_leader_report_generation, args=(analysis_id,))
        thread.daemon = True
        thread.start()

        return jsonify(
            {"success": True, "analysis_id": analysis_id, "redirect_url": url_for("progress", analysis_id=analysis_id)}
        )

    except Exception as e:
        logger.error(f"[[ERROR]] Error starting leader report: {e}")
        return jsonify({"success": False, "error": "Failed to start leader report"}), 500


def run_leader_report_generation(analysis_id):
    """Background thread to generate leader report"""
    # Round 5 / Phase 6.14: bind the analysis ID for correlated logs.
    try:
        from structured_logging import bind_analysis_id as _bind_aid

        _bind_aid(analysis_id)
    except Exception:
        pass  # noqa: PIE790
    ctx = None
    try:
        with analysis_status_lock:
            status = analysis_status[analysis_id]
            status["status"] = "running"
            status["completed_steps"] = []
            _update_progress(status, 2, "Connecting to Snowflake (CSConsole data)...", "Database Connection")

        manager = status["manager"]
        days = status["days"]
        csone_file = status.get("csone_file")
        # Round 142: reconstruct the canonical scope from persisted status.
        # Defaults preserve queued jobs created before scope fields existed.
        scope_type = str(status.get("scope_type", "team") or "team").strip().lower()
        scope_value = str(status.get("scope_value", "") or "").strip()
        scope_member = str(status.get("scope_member", "") or "").strip()
        try:
            scope_selection = validate_leader_scope_request(
                manager,
                scope_type,
                scope_value,
                TEAM_ROSTER,
                member_email=scope_member,
            )
        except LeaderScopeValidationError as scope_error:
            with analysis_status_lock:
                status["status"] = "error"
                status["error"] = "Invalid Leader report scope"
                status["message"] = str(scope_error)
                status["end_time"] = _now_utc_iso_z()
                save_analysis_status()
            return

        # Callback closure for leader_report_generator to push sub-step updates
        def leader_progress_cb(pct, msg, step):
            with analysis_status_lock:
                _update_progress(status, pct, msg, step)

        logger.info(f"Connecting to Snowflake for leader report...")
        # Round 161: shared prefetch meta for R153 source vs evaluation clocks.
        _leader_prefetch_meta: Dict[str, Any] = {
            "attempted_at": _now_utc_iso_z(),
            "outcome": "attempting",
        }
        try:
            ctx = _connect_with_keeper()
            logger.info(f"SUCCESS: Connected to Snowflake")
        except Exception as conn_error:
            error_msg = str(conn_error)

            if any(
                keyword in error_msg.lower()
                for keyword in ["not allowed to access", "failed to connect", "network", "timeout"]
            ):
                logger.error(f"ERROR: Snowflake connection failed - VPN may not be connected")

                with analysis_status_lock:
                    status["status"] = "error"
                    status["error"] = "VPN Connection Required"
                    status["message"] = (
                        "ERROR: Unable to connect to Snowflake database.\n\n"
                        "Leader Reports require access to both:\n"
                        "• CSConsole data (Action Plans, Adoption Barriers, Customer Pulse) - requires Cisco VPN\n"
                        "• CSOne data (TAC cases) - from uploaded Excel file\n\n"
                        "ACTION REQUIRED:\n"
                        "1. Connect to Cisco VPN\n"
                        "2. Verify VPN is active and connected\n"
                        "3. Try generating the report again\n\n"
                        "Without VPN connection, the report cannot access team member subscriptions, "
                        "customers, or CSConsole activities from Snowflake."
                    )
                    status["completion_time"] = _now_utc_iso_z()
                    save_analysis_status()

                return
            else:
                raise

        if check_cancellation(analysis_id):
            update_analysis_status(analysis_id, {"status": "cancelled", "message": "Analysis cancelled by user"})
            return

        with analysis_status_lock:
            _update_progress(status, 5, "Connected to Snowflake. Fetching team subscriptions...", "Team Data Retrieval")

        # Fetch team subscriptions first (needed to scope CSOne to manager's portfolio)
        team_subs_df = pd.DataFrame()
        _r142_team_subs_fetch_succeeded = False
        try:
            cssm_emails = [email for mgr, name, email in TEAM_ROSTER if mgr == manager]
            if cssm_emails:
                team_subs_df = get_subscriptions_for_team(ctx, cssm_emails)
                _r142_team_subs_fetch_succeeded = True
                logger.info(f"[[OK]] Retrieved {len(team_subs_df)} team subscriptions for {manager}")
                # Round 82 / Phase A4: persist primary+secondary attribution diag.
                _r82_persist_team_subs_diag(status, team_subs_df)
        except Exception as e:
            logger.warning(f"[[WARNING]] Failed to fetch team subscriptions: {e}")

        # Round 142: filter only after the trusted manager-wide subscription
        # fetch. This is the server-side customer authorization check; a
        # customer absent from the selected manager/member portfolio fails
        # closed before CSOne or report generation can widen the scope.
        if _r142_team_subs_fetch_succeeded:
            try:
                team_subs_df = filter_leader_subscriptions(team_subs_df, scope_selection)
            except LeaderScopeValidationError as scope_error:
                with analysis_status_lock:
                    status["status"] = "error"
                    status["error"] = "Leader report scope validation failed"
                    status["message"] = str(scope_error)
                    status["end_time"] = _now_utc_iso_z()
                    save_analysis_status()
                return

        # Phase 1.1 / Round 38 / Phase 2: Two-pass data validation for
        # the leader report.
        #
        # ``Pass 1`` (early) checks ONLY the absolute prerequisites
        # (Snowflake connectivity + at least one team subscription).
        # CSOne is intentionally NOT promoted to required here, even
        # if a file path was resolved upstream.  Pre-Round-38 the
        # early validator received ``csone_file_provided=True`` from
        # any path (including the OneDrive autodiscovery fallback)
        # which combined with ``csone_data=pd.DataFrame()`` (the file
        # had not been loaded yet) caused a hard "csone missing or
        # empty" error before the worker ever opened the file -- the
        # exact false-positive Round 38 fixes.
        #
        # ``Pass 2`` (later, after the CSOne file is actually loaded)
        # only fails loud if the operator EXPLICITLY uploaded a
        # CSOne file (``status['csone_file_was_uploaded']`` set by
        # the endpoint).  An OneDrive-autodiscovered file that
        # produces zero scoped rows is logged + emitted as a
        # ``partial_data_warnings`` entry but does not abort the
        # report.
        logger.info("[[VALIDATION]] Pass 1: validating Snowflake + team subscriptions for leader report...")
        _r30_leader_partial_warnings: List[Dict[str, Any]] = []
        _leader_required_pass1 = ["snowflake", "team_subscriptions"]
        try:
            raise_validation_error_if_invalid(
                report_type="leader",
                snowflake_ctx=ctx,
                team_subs_df=team_subs_df,
                ab_data=pd.DataFrame(),
                csone_data=pd.DataFrame(),
                required_sources=_leader_required_pass1,
                # Round 38 / Phase 2: csone is validated in Pass 2
                # below against the actual loaded DataFrame, not at
                # Pass 1 against a pre-load empty placeholder.
                csone_file_provided=False,
            )
            logger.info("[[VALIDATION]] Pass 1 OK: Snowflake + team subscriptions validated")

            # Round 30 / M4: collect any optional fetch errors via a
            # non-raising re-validation so we can promote them into a
            # ``leader_partial_data_warnings`` list that drives the leader
            # Word/Excel partial-data banner.  Leader path doesn't carry
            # csconsole_* frames here, so this primarily covers any
            # future expansion -- we still run it for symmetry.  Note:
            # this runs against the same pre-load empty csone_data as
            # Pass 1 because optional CSOne fetch errors are not a thing
            # (the csone file is loaded synchronously below, not fetched
            # via an optional API).
            try:
                from data_source_validator import (
                    validate_data_sources_for_report as _r30_validate,
                    get_optional_fetch_errors as _r30_opt_errs,
                )

                _r30_is_valid, _r30_missing, _r30_err_details = _r30_validate(
                    report_type="leader",
                    snowflake_ctx=ctx,
                    team_subs_df=team_subs_df,
                    ab_data=pd.DataFrame(),
                    csone_data=pd.DataFrame(),
                    required_sources=_leader_required_pass1,
                    csone_file_provided=False,
                )
                _r30_opt = _r30_opt_errs(_r30_err_details)
                for _src_key, _src_err in (_r30_opt or {}).items():
                    _r30_leader_partial_warnings.append(
                        {
                            "dataset": _src_key,
                            "error": _redact_partial_warning_error(_src_err),
                            "kind": "optional_fetch_failed",
                            "effect": (
                                f"Optional source '{_src_key}' failed to load; "
                                "dependent leader-report sections render with "
                                "reduced detail."
                            ),
                        }
                    )
            except Exception as _r30_pdw_err:  # noqa: BLE001
                logger.debug(
                    "Round 30 / M4: leader optional fetch error promotion skipped: %s",
                    _r30_pdw_err,
                )
        except DataSourceValidationError as ve:
            logger.error(f"[[VALIDATION]] Pass 1 failed: {ve}")
            with analysis_status_lock:
                status["status"] = "error"
                status["error"] = "Leader report data validation failed"
                status["message"] = (
                    f"Leader report cannot be generated: {', '.join(ve.missing_sources)} "
                    "missing or empty. See logs for details."
                )
                status["completion_time"] = _now_utc_iso_z()
                save_analysis_status()
            return

        # Round 38 / Phase 3: CSOne file load was relocated UP to here
        # (was previously at the end of this function block, after the
        # broken validator).  Loading first lets Pass 2 below validate
        # against the real DataFrame instead of a pre-load empty
        # placeholder.
        with analysis_status_lock:
            _update_progress(status, 8, "Loading and scoping CSOne data...", "CSOne Processing")

        # Load and scope CSOne data to team portfolio (same approach as Comprehensive report)
        csone_df = pd.DataFrame()
        _r161_csone_raw_rows = 0
        _r161_csone_scoped_rows = 0
        _r161_scope_customer_count = 0
        # Resolve CSOne path safely (prevents path traversal)
        csone_path = _resolve_csone_path_safe(csone_file) if csone_file else None
        # When no file provided: try OneDrive folder (macro places reports daily).
        # Round 38 / Phase 3: this fallback already ran in the endpoint
        # (``/run_leader``) when computing ``csone_file_autopicked``;
        # the second call here is a belt-and-suspenders refresh for
        # workers that were started directly (e.g. tests) without
        # going through the endpoint provenance split.
        if not csone_path:
            csone_path = get_latest_csone_from_folder()
        if csone_path and os.path.exists(csone_path):
            logger.info(f"[[FILE]] Loading CSOne data from {csone_path}")
            csone_df_raw = load_csone_excel(csone_path)
            raw_count = len(csone_df_raw) if csone_df_raw is not None and not csone_df_raw.empty else 0
            _r161_csone_raw_rows = int(raw_count)
            logger.info(f"[[FILE]] Raw CSOne file: {raw_count} cases")
            if raw_count == 0 and csone_path:
                _empty_kind = (
                    "adoptiq_output_artifact"
                    if _r161_2_is_adoptiq_output_csone_filename(csone_path)
                    else "csone_file_empty_after_load"
                )
                _r30_leader_partial_warnings.append(
                    {
                        "dataset": "csone",
                        "kind": _empty_kind,
                        "effect": (
                            "Autodiscovered CSOne file parsed to zero TAC rows; TAC/BEMS evidence "
                            "is unavailable rather than zero."
                        ),
                    }
                )

            csone_df_prepared = _prepare_csone(
                csone_df_raw if csone_df_raw is not None else pd.DataFrame(), team_subs_df
            )
            if not team_subs_df.empty:
                # Scope to team portfolio: team customers, date range (same as Comprehensive)
                team_customer_names = team_subs_df["BU_NAME"].dropna().unique().tolist()
                _r161_scope_customer_count = int(len(team_customer_names))
                sub_ids = team_subs_df["SUBSCRIPTION_ID"].dropna().unique().tolist()
                csone_df = _apply_scope_filter_csone(csone_df_prepared, "All", days, sub_ids, team_customer_names)
                csone_df.attrs.update(
                    {
                        "scope_validated": True,
                        "scope_type": scope_selection.scope_type,
                        "scope_value": scope_selection.display_value,
                        "source_system": "CSOne",
                    }
                )
                csone_count = len(csone_df)
                _r161_csone_scoped_rows = int(csone_count)
                logger.info(
                    f"[[OK]] Scoped to team portfolio: {csone_count} TAC cases in scope (from {raw_count} in file)"
                )
            else:
                # Fallback: no team subscriptions - filter by date only to avoid irrelevant cases
                csone_df = _apply_scope_filter_csone_inclusive(csone_df_prepared, "All", days)
                csone_count = len(csone_df)
                _r161_csone_scoped_rows = int(csone_count)
                logger.warning(f"[[WARNING]] No team subscriptions - using {csone_count} cases (date filter only)")

            # Round 161: persist scoped CSOne diagnostics for admin/status JSON.
            with analysis_status_lock:
                status["csone_path"] = str(csone_path or "")
                status["csone_raw_rows"] = _r161_csone_raw_rows
                status["csone_scoped_rows"] = _r161_csone_scoped_rows
                status["scope_customer_count"] = _r161_scope_customer_count

            with analysis_status_lock:
                _update_progress(status, 12, f"Loaded {csone_count} TAC cases in scope for team...", "CSOne Processing")
        else:
            csone_df.attrs["source_unavailable"] = True
            csone_df.attrs["source_unavailable_detail"] = (
                "no CSOne source file was supplied or discovered for this Leader run"
            )
            with analysis_status_lock:
                status["csone_path"] = ""
                status["csone_raw_rows"] = 0
                status["csone_scoped_rows"] = 0
                status["scope_customer_count"] = (
                    int(team_subs_df["BU_NAME"].dropna().nunique()) if not team_subs_df.empty else 0
                )
            _r30_leader_partial_warnings.append(
                {
                    "dataset": "csone",
                    "kind": "source_unavailable",
                    "effect": (
                        "No CSOne source file was supplied or discovered; TAC, BEMS, and dependent risk evidence "
                        "are unavailable rather than zero."
                    ),
                }
            )

        # Round 38 / Phase 2: Pass 2 validation -- fail loud iff the
        # operator EXPLICITLY uploaded a CSOne file but the loaded
        # DataFrame is empty.  OneDrive-autodiscovered hits never
        # raise here; they get a partial_data_warning so the report
        # banner is honest, then continue with reduced detail.
        _csone_was_uploaded = bool(status.get("csone_file_was_uploaded"))
        if _csone_was_uploaded:
            try:
                raise_validation_error_if_invalid(
                    report_type="leader",
                    snowflake_ctx=ctx,
                    team_subs_df=team_subs_df,
                    ab_data=pd.DataFrame(),
                    # Pass 2 sees the REAL loaded csone_df.  An empty
                    # frame here means the explicit upload genuinely
                    # produced zero rows after scoping -- the exact
                    # condition Round 2 / Phase 4.3 was designed to
                    # surface.
                    csone_data=csone_df,
                    required_sources=["csone"],
                    csone_file_provided=True,
                )
                logger.info("[[VALIDATION]] Pass 2 OK: explicit CSOne upload contains scoped TAC cases")
            except DataSourceValidationError as ve:
                logger.error(f"[[VALIDATION]] Pass 2 failed (explicit upload empty after scope): {ve}")
                with analysis_status_lock:
                    status["status"] = "error"
                    status["error"] = "Leader report data validation failed"
                    status["message"] = (
                        f"Leader report cannot be generated: {', '.join(ve.missing_sources)} "
                        "missing or empty. See logs for details."
                    )
                    status["completion_time"] = _now_utc_iso_z()
                    save_analysis_status()
                return
        elif csone_df.empty and csone_path:
            # Autodiscovery picked something up but it scoped to zero
            # rows.  Honest banner, no abort.
            try:
                _autopicked_basename = os.path.basename(csone_path)
            except Exception:
                _autopicked_basename = "<unknown>"
            logger.warning(
                "[[VALIDATION]] Leader: autodiscovered CSOne file %s scoped to "
                "zero TAC cases for this team/period; continuing with degraded report",
                _autopicked_basename,
            )
            _r30_leader_partial_warnings.append(
                {
                    "dataset": "csone",
                    "kind": "autodiscovered_empty_after_scope",
                    "effect": (
                        "OneDrive-autodiscovered CSOne file produced zero TAC cases "
                        "after scoping to this manager's team and the selected window. "
                        "Leader-report TAC sections render with reduced detail."
                    ),
                }
            )

        with analysis_status_lock:
            _update_progress(
                status, 13, "Gathering external intelligence (defects, incidents)...", "External Intelligence"
            )
        logger.info(f"[[WEB]] Gathering external intelligence for leader report...")
        _r142_leader_external_sources_available = True
        try:
            ext_bugs = fetch_help_webex_bugs()
            _inc_days = int(days) if isinstance(locals().get("days"), (int, float)) and locals().get("days") else 365
            ext_incidents = fetch_status_incidents(days_back=_inc_days)
            logger.info(f"[[OK]] External intelligence gathered: {len(ext_bugs)} bugs, {len(ext_incidents)} incidents")
        except Exception as e:
            logger.warning(f"[[WARNING]] External intelligence gathering failed: {e}")
            ext_bugs = []
            ext_incidents = []
            _r142_leader_external_sources_available = False
            _r30_leader_partial_warnings.append(
                {
                    "dataset": "external_intelligence",
                    "kind": "runtime",
                    "error": _redact_partial_warning_error(e) or "fetch_failed",
                    "effect": "External bug and incident sources are unavailable for this run.",
                }
            )

        # Round 145: the explicit local acceptance runner may supply a
        # deterministic fixture clock through in-memory Flask config. Normal
        # startup never sets this key and remains on the real UTC clock. This
        # is deliberately not environment-driven and imports no fixture code.
        _r145_as_of_override = app.config.get("LOCAL_ACCEPTANCE_AS_OF_UTC")
        if _r145_as_of_override:
            try:
                _r142_leader_as_of = datetime.fromisoformat(
                    str(_r145_as_of_override).replace("Z", "+00:00")
                ).astimezone(timezone.utc)
            except (TypeError, ValueError):
                raise ValueError("Invalid local acceptance as-of timestamp") from None
        else:
            _r142_leader_as_of = datetime.now(timezone.utc)
        _r142_leader_technology = str(status.get("technology") or status.get("tech") or "All").strip() or "All"
        with analysis_status_lock:
            status["evaluation_as_of_utc"] = _r142_leader_as_of.isoformat()

        with analysis_status_lock:
            _update_progress(status, 15, "Extracting software defects and PSIRT vulnerabilities...", "Defect Analysis")
        logger.info(f"[[DEFECTS]] Extracting software defects and PSIRT vulnerabilities...")
        software_defects = extract_software_defects(csone_df, pd.DataFrame()) if not csone_df.empty else None
        psirt_vulns = extract_psirt_vulnerabilities(csone_df, pd.DataFrame()) if not csone_df.empty else None
        if software_defects:
            logger.info(f"[[DEFECTS]] Found {software_defects.get('total_defects', 0)} defects")
        if psirt_vulns:
            logger.info(f"[[PSIRT]] Found {psirt_vulns.get('total_vulnerabilities', 0)} vulnerabilities")

        if check_cancellation(analysis_id):
            update_analysis_status(analysis_id, {"status": "cancelled", "message": "Analysis cancelled by user"})
            return

        with analysis_status_lock:
            _update_progress(status, 17, "Preparing to generate Word document...", "Data Collection")

        logger.info(f"[[WRITE]] Generating leader report for {manager}...")

        if ctx is None:
            raise Exception("Database connection failed. Please check your VPN connection and try again.")

        # Round 30 / H1b: forward the optional ``arr_impact`` so the
        # leader title-page can render the multi-currency advisory.
        # ``arr_impact`` is populated by ``calculate_arr_impact_for_issues``
        # earlier in the orchestration flow; it may be missing here when
        # the leader runs standalone, so default to an empty dict.
        _r30_leader_arr_impact = (
            arr_impact  # noqa: F821 (conditionally bound; guarded by 'in locals()')
            if "arr_impact" in locals() and isinstance(arr_impact, dict)  # noqa: F821
            else None
        )

        # Round 30 / M2: derive ``intel_truncated`` / ``intel_fetch_limit``
        # from the live-fetched feeds so the leader Word output can render
        # an explicit "table truncated" disclosure when the storage cap was
        # reached.  Mirrors the executive path in ``run_compact_analysis``.
        _r30_leader_intel_fetch_limit: Optional[int] = 500
        _r30_leader_intel_truncated: Dict[str, bool] = {}
        try:
            _r30_lead_inc_trunc = False
            _ext_incidents = locals().get("ext_incidents") or []
            if isinstance(_ext_incidents, list) and _ext_incidents:
                _wm = _ext_incidents[-1].get("_window_meta") if isinstance(_ext_incidents[-1], dict) else None
                if isinstance(_wm, dict):
                    _r30_lead_inc_trunc = bool(_wm.get("truncated"))
            _r30_lead_bug_trunc = False
            _ext_bugs = locals().get("ext_bugs") or []
            if isinstance(_ext_bugs, list):
                _r30_lead_bug_trunc = len(_ext_bugs) >= _r30_leader_intel_fetch_limit
            _r30_leader_intel_truncated = {
                "incidents": _r30_lead_inc_trunc,
                "bugs": _r30_lead_bug_trunc,
            }
        except Exception as _r30_lead_trunc_err:  # noqa: BLE001
            logger.debug(
                "Round 30 / M2: leader intel_truncated derivation failed (continuing): %s",
                _r30_lead_trunc_err,
            )
            _r30_leader_intel_truncated = {}
            _r30_leader_intel_fetch_limit = None

        filepath, success_msg, team_data = generate_leader_report(
            manager_name=manager,
            days=days,
            technology=_r142_leader_technology,
            ctx=ctx,
            team_roster=TEAM_ROSTER,
            data_retrieved_at=_r142_leader_as_of,
            # Round 142: the generator receives both the canonical request and
            # the already-filtered subscription frame so it cannot re-expand
            # an individual report back to the manager's whole portfolio.
            scope_type=scope_selection.scope_type,
            scope_value=scope_selection.scope_value,
            scope_member=scope_selection.member_email,
            scoped_subscriptions_df=team_subs_df,
            csone_df=csone_df,
            ext_bugs=(ext_bugs if _r142_leader_external_sources_available else None),
            ext_incidents=(ext_incidents if _r142_leader_external_sources_available else None),
            software_defects=software_defects if "software_defects" in locals() else None,
            psirt_vulns=psirt_vulns if "psirt_vulns" in locals() else None,
            progress_callback=leader_progress_cb,
            arr_impact=_r30_leader_arr_impact,
            # Round 30 / M2: surface external-intelligence truncation in the
            # leader Word output so the reader cannot mistake a capped
            # sample of help.webex bugs / status.webex incidents for the
            # full universe.
            intel_truncated=_r30_leader_intel_truncated,
            intel_fetch_limit=_r30_leader_intel_fetch_limit,
            # Round 30 / M4: forward promoted optional-source fetch errors so
            # the leader title page can render an explicit Partial Data
            # Warning banner instead of letting empty optional sections look
            # like clean zeros.
            partial_data_warnings=_r30_leader_partial_warnings,
            # Round 81 / Build 57: route the leader docx into
            # ``<outputs>/<Manager>/Leader/`` instead of the flat
            # legacy ``<outputs>/`` so the per-manager folder
            # invariant matches Compact / Renewal / Comprehensive.
            output_dir=_r81_resolve_report_output_dir(manager, "Leader"),
            leader_prefetch_meta=_leader_prefetch_meta,
        )

        # Round 161: project source freshness onto status after CSConsole fetch.
        _r161_leader_freshness = _r147_compact_prefetch_freshness(
            _leader_prefetch_meta,
            outcome=_leader_prefetch_meta.get("outcome"),
            evaluation_clock=_r142_leader_as_of,
        )
        _r161_leader_freshness_warning = _r161_leader_freshness.get("warning")
        if _r161_leader_freshness_warning and not any(
            isinstance(item, dict) and item.get("dataset") == "data_freshness"
            for item in _r30_leader_partial_warnings
        ):
            _r30_leader_partial_warnings.append(_r161_leader_freshness_warning)
        with analysis_status_lock:
            status["data_retrieved_at"] = _r161_leader_freshness.get("data_retrieved_at") or ""
            status["data_as_of_utc"] = _r161_leader_freshness.get("data_as_of_utc") or ""
            status["data_as_of_state"] = _r161_leader_freshness.get("data_as_of_state") or "unavailable"
            status["data_as_of_detail"] = _r161_leader_freshness.get("data_as_of_detail") or ""
            status["retrieval_attempted_at_utc"] = _r161_leader_freshness.get("retrieval_attempted_at") or ""
            if not status.get("evaluation_as_of_utc"):
                status["evaluation_as_of_utc"] = _r161_leader_freshness.get("evaluation_as_of_utc") or ""

        if check_cancellation(analysis_id):
            update_analysis_status(analysis_id, {"status": "cancelled", "message": "Analysis cancelled by user"})
            return

        with analysis_status_lock:
            _update_progress(status, 82, "Generating Excel workbook...", "Excel Report Generation")

        # Phase 1.1: Run validate_report_consistency on the aggregated leader
        # bundle so the leader report path is contract-checked the same way the
        # comprehensive / compact / EI paths already are.
        try:
            agg_ab_frames = []
            agg_tac_frames = []
            agg_pulse_frames = []
            for _cssm_name, _data in (team_data or {}).items():
                _ab = _data.get("adoption_barriers", pd.DataFrame())
                if isinstance(_ab, pd.DataFrame) and not _ab.empty:
                    agg_ab_frames.append(_ab)
                _tac = _data.get("tac_cases", pd.DataFrame())
                if isinstance(_tac, pd.DataFrame) and not _tac.empty:
                    agg_tac_frames.append(_tac)
                _pulse = _data.get("customer_pulse", pd.DataFrame())
                if isinstance(_pulse, pd.DataFrame) and not _pulse.empty:
                    agg_pulse_frames.append(_pulse)
            agg_ab = pd.concat(agg_ab_frames, ignore_index=True) if agg_ab_frames else pd.DataFrame()
            agg_tac = pd.concat(agg_tac_frames, ignore_index=True) if agg_tac_frames else pd.DataFrame()
            agg_pulse = pd.concat(agg_pulse_frames, ignore_index=True) if agg_pulse_frames else pd.DataFrame()
            # Round 2 / Phase 4.5: ``pd.concat`` drops ``DataFrame.attrs``
            # so the per-customer ``fetch_error`` / ``row_contract`` flags
            # would be silently lost on the aggregate frame.  Re-stamp:
            #   * ``fetch_error`` becomes the union of any per-frame
            #     fetch errors so consistency checks can detect
            #     "some customers' AB fetch failed" instead of treating
            #     a partial aggregate as fully successful.
            #   * ``row_contract`` is re-derived via
            #     ``annotate_with_contract`` so the contract dashboard
            #     reflects the aggregate's real columns.
            try:
                from data_contracts import annotate_with_contract as _annotate
            except Exception:
                _annotate = None  # type: ignore

            def _restamp_aggregate(
                agg_df: "pd.DataFrame", source_frames: "list[pd.DataFrame]", dataset: "Optional[str]"
            ) -> "pd.DataFrame":
                if not isinstance(agg_df, pd.DataFrame):
                    return agg_df
                # Union per-frame fetch_error attrs onto the aggregate so
                # downstream renderers can detect partial failures.
                fetch_errors = []
                fetch_kinds = []
                for _src in source_frames or []:
                    _attrs = getattr(_src, "attrs", {}) or {}
                    _err = _attrs.get("fetch_error")
                    if _err:
                        fetch_errors.append(str(_err))
                    _kind = _attrs.get("fetch_error_kind")
                    if _kind:
                        fetch_kinds.append(str(_kind))
                if fetch_errors:
                    try:
                        agg_df.attrs["fetch_error"] = "; ".join(sorted(set(fetch_errors)))
                        if fetch_kinds:
                            agg_df.attrs["fetch_error_kind"] = (
                                "partial_aggregate" if len(set(fetch_kinds)) > 1 else fetch_kinds[0]
                            )
                        agg_df.attrs["fetch_error_partial"] = True
                    except Exception:
                        # Round 4: non-fatal; suppressed silently in original code
                        pass  # noqa: PIE790
                if dataset and _annotate is not None and not agg_df.empty:
                    try:
                        _annotate(agg_df, dataset=dataset)
                    except Exception:
                        # Round 4: non-fatal; suppressed silently in original code
                        pass  # noqa: PIE790
                return agg_df

            agg_ab = _restamp_aggregate(agg_ab, agg_ab_frames, "adoption_barriers")
            agg_tac = _restamp_aggregate(agg_tac, agg_tac_frames, "tac_cases")
            agg_pulse = _restamp_aggregate(agg_pulse, agg_pulse_frames, "customer_pulse")
            # Round 2 / Phase 1.11: thread extra_frames + the
            # account_to_customer mapping so the validator counts
            # subscription-only / pulse-only customers in the same
            # universe the leader report does.
            # Round 14 / Phase 2.4: replace the
            # ``team_subs_df_unfiltered if 'team_subs_df_unfiltered' in
            # locals() else pd.DataFrame()`` antipattern with an
            # explicit ``locals().get`` so the bare name is no longer a
            # ruff F821, and so the intent (use the unfiltered frame
            # only if it has been bound earlier in the function) is
            # easier to read.  Behavior is identical because the
            # short-circuit short-circuited identically.
            try:
                _scope_locals = locals()
                _team_subs_unfiltered_for_lookup = _scope_locals.get("team_subs_df_unfiltered")
                if not isinstance(_team_subs_unfiltered_for_lookup, pd.DataFrame):
                    _team_subs_unfiltered_for_lookup = pd.DataFrame()
                _leader_lookup = build_customer_lookup(_team_subs_unfiltered_for_lookup)
                _leader_a2c = (_leader_lookup or {}).get("account_to_customer", {}) or {}
            except Exception:
                _leader_a2c = {}
            _leader_extra_frames = []
            for _name in (
                "team_subs_df_unfiltered",
                "csconsole_customer_pulse",
                "csconsole_success_priorities",
                "csconsole_adoption_barriers",
                "ap_df",
            ):
                _val = locals().get(_name)
                if isinstance(_val, pd.DataFrame) and not _val.empty:
                    _leader_extra_frames.append(_val)
            # Round 5 / Phase 5.1: previously the leader path called
            # ``validate_report_consistency`` WITHOUT a
            # ``portfolio_metrics=`` kwarg, which meant the validator
            # had to re-derive customer counts / risk distributions
            # from the AB+TAC frames alone.  That re-derivation does
            # not see subscription-only customers and disagrees with
            # the canonical metrics that the EI / compact paths
            # publish, so the leader report could pass consistency
            # while the same dataset failed it on every other path.
            # Build a leader-scope ``PortfolioMetrics`` first and
            # thread it through so all paths use the same source of
            # truth.
            # Round 14 / Phase 2.4: replace the
            # ``team_subs_df_unfiltered if 'team_subs_df_unfiltered' in
            # locals() and isinstance(...) else pd.DataFrame()`` antipattern
            # with an explicit ``locals().get`` lookup so the bare name
            # stops tripping ruff F821.  Behavior is preserved.
            try:
                _scope_locals = locals()
                _team_subs_unfiltered_for_pm = _scope_locals.get("team_subs_df_unfiltered")
                if not isinstance(_team_subs_unfiltered_for_pm, pd.DataFrame):
                    _team_subs_unfiltered_for_pm = pd.DataFrame()
                # Round 42 / Phase 3: dropped the invalid
                # ``customer_subs=`` and ``customer_pulse_df=`` kwargs.
                # ``canonical_metrics.build_portfolio_metrics`` (signature
                # at ``canonical_metrics.py:1435-1444``) accepts neither;
                # passing them ALWAYS raised ``TypeError: ... unexpected
                # keyword argument 'customer_subs'``.  The except block
                # below silently swallowed it as ``logger.debug`` and set
                # ``_leader_portfolio_metrics = None``.  Result: the
                # validator's ``if portfolio_metrics:`` block at
                # ``report_consistency.py:280`` never fired on the leader
                # path, so leader runs silently bypassed every PM parity
                # check that compact / EI / renewal enforce.  The
                # ``team_subs_df_unfiltered`` customer universe is still
                # threaded into ``_leader_extra_frames`` upstream when
                # needed, and the customer-pulse universe is wired into
                # the validator separately via ``pulse_df=`` at
                # ``report_consistency.py:71``.
                # Round 43 / Phase 4: drop ``extra_customer_frames=`` and
                # ``account_to_customer=`` from this call so the leader
                # headline narrows to ``count_customers(ab_df=, csone_df=,
                # pulse_df=)`` -- matching the Round 25 / Phase A contract that
                # the Word headline must mirror the Excel Summary row.  Pre-fix
                # the leader path passed both extras, which inflated
                # ``_leader_portfolio_metrics["total_customers"]`` to 40
                # (wider universe with team subs) while the validator at
                # ``report_consistency.py:318`` computed 46 (narrow AB ∪
                # CSOne ∪ Pulse) and raised
                # ``[[CONSISTENCY]] Leader consistency check skipped:
                # Portfolio metric mismatch: total_customers=40 (Word headline)
                # != 46 (canonical AB ∪ CSOne ∪ Pulse universe).`` on the
                # build-19 demo leader run (
                # ``Leader_Brian_Frazier_90d_1777428669``).  The validator
                # call below STILL receives ``extra_frames=_leader_extra_frames``
                # / ``account_to_customer=_leader_a2c`` for per-section
                # defect/customer linkage, so wider counts remain available
                # downstream -- only the headline tile narrows.  This restores
                # the Round 42 / Phase 3 PM parity check that was being
                # silently skipped via the ``except`` warning at L20242.
                _leader_portfolio_metrics = cm.build_portfolio_metrics(
                    ab_df=agg_ab,
                    csone_df=agg_tac,
                    risk_scale=cm.RISK_SCALE_0_TO_10,
                )
            except Exception as _lpm_err:
                # Round 42 / Phase 3: promoted from logger.debug to
                # logger.warning so future signature drift surfaces in
                # ops logs rather than silently re-introducing the
                # always-skip behaviour the Phase 3 fix just removed.
                logger.warning(
                    "Round 42: leader portfolio_metrics build failed; "
                    "falling back to validator's internal derivation "
                    "(this should not happen post-Phase-3 -- "
                    "investigate signature drift): %s",
                    _lpm_err,
                )
                _leader_portfolio_metrics = None
            # Round 6 / Phase 5.8: thread ``strict_mode`` and any
            # leader-narrative factual_claims through the validator so
            # the leader path matches the comprehensive path's enforcement
            # model and a single env toggle governs all reports.
            _leader_strict = str(os.getenv("ADOPTIQ_NONSTRICT_CONSISTENCY", "0")).strip().lower() not in {
                "1",
                "true",
                "yes",
                "on",
            }
            _leader_factual_claims: list = []
            for _claim_attr in ("leader_factual_claims", "factual_claims", "leader_key_findings"):
                _claim_val = locals().get(_claim_attr)
                if isinstance(_claim_val, list):
                    _leader_factual_claims.extend([str(c) for c in _claim_val if c])
            leader_consistency = validate_report_consistency(
                agg_ab,
                agg_tac,
                customer_pulse_df=agg_pulse if not agg_pulse.empty else None,
                extra_frames=_leader_extra_frames or None,
                account_to_customer=_leader_a2c or None,
                portfolio_metrics=_leader_portfolio_metrics,
                strict_mode=_leader_strict,
                factual_claims=_leader_factual_claims or None,
            )
            if not leader_consistency.get("is_valid", True):
                logger.error(f"[[CONSISTENCY]] Leader report errors: {leader_consistency.get('errors')}")
            if leader_consistency.get("warnings"):
                logger.warning(f"[[CONSISTENCY]] Leader report warnings: {leader_consistency.get('warnings')}")
        except Exception as _lcerr:
            logger.warning(f"[[CONSISTENCY]] Leader consistency check skipped: {_lcerr}")

        # Generate Excel file with team data
        excel_path = None
        try:
            logger.info(f"[[DATA]] Generating Excel file for leader report (reusing team_data from Word generation)...")

            # Prepare Excel file path
            base_path = str(Path(filepath).with_suffix(""))
            excel_path = f"{base_path}.xlsx"

            # Collect all team data into DataFrames for Excel
            all_action_plans = []
            all_adoption_barriers = []
            all_customer_pulse = []
            all_success_priorities = []
            all_tac_cases = []
            all_subscriptions = []

            for cssm_name, data in team_data.items():
                # Action Plans
                if not data.get("action_plans", pd.DataFrame()).empty:
                    ap_df = data["action_plans"].copy()
                    ap_df["CSSM"] = cssm_name
                    all_action_plans.append(ap_df)

                # Adoption Barriers
                if not data.get("adoption_barriers", pd.DataFrame()).empty:
                    ab_df = data["adoption_barriers"].copy()
                    ab_df["CSSM"] = cssm_name
                    all_adoption_barriers.append(ab_df)

                # Customer Pulse
                if not data.get("customer_pulse", pd.DataFrame()).empty:
                    cp_df = data["customer_pulse"].copy()
                    cp_df["CSSM"] = cssm_name
                    all_customer_pulse.append(cp_df)

                # Success Priorities
                if not data.get("success_priorities", pd.DataFrame()).empty:
                    sp_df = data["success_priorities"].copy()
                    sp_df["CSSM"] = cssm_name
                    all_success_priorities.append(sp_df)

                # TAC Cases
                if not data.get("tac_cases", pd.DataFrame()).empty:
                    tac_df = data["tac_cases"].copy()
                    tac_df["CSSM"] = cssm_name
                    all_tac_cases.append(tac_df)

                # Subscriptions
                if not data.get("subscriptions", pd.DataFrame()).empty:
                    sub_df = data["subscriptions"].copy()
                    sub_df["CSSM"] = cssm_name
                    all_subscriptions.append(sub_df)

            # Combine all DataFrames
            sheets = {}

            # Always build a Team_Summary sheet so the Excel file is never empty
            # Round 125 / D1: the per-CSSM ``Num_*`` cells previously
            # held a RAW ``len(frame)`` row count. When a single AP / AB /
            # CP / SP / TAC row is attributed to multiple CSSMs via the
            # R72 ``_ATTRIBUTED_BY_ACCOUNT`` shared-account pathway, the
            # SAME source ID appears in more than one per-CSSM frame, so
            # the per-person rows raw-summed ABOVE the cross-CSSM-deduped
            # headline (Build 93/Brian: 655/44/72 per-person vs 553/39/62
            # deduped). Two-pronged fix: (a) count distinct source IDs
            # per person (collapses any intra-person duplication), and
            # (b) append an explicit ``TOTAL (deduped)`` row built from
            # the cross-CSSM-deduped union so the column foots to the
            # XLSX sheet + the docx headline. Per-person rows still sum
            # ABOVE the TOTAL when shared accounts exist -- that is
            # expected (a shared AP is legitimately attributed to each
            # owner) and is now labelled honestly.
            def _r139_distinct_tac_count(_df) -> int:
                if not isinstance(_df, pd.DataFrame) or _df.empty:
                    return 0
                try:
                    from data_normalization import resolve_tac_case_id

                    ids = []
                    no_id = 0
                    for _, row in _df.iterrows():
                        token = resolve_tac_case_id(row)
                        if token:
                            ids.append(token)
                        else:
                            no_id += 1
                    return len(set(ids)) + no_id
                except Exception:
                    return _r125_distinct_id_count(_df)

            def _r125_distinct_id_count(_df) -> int:
                if not isinstance(_df, pd.DataFrame) or _df.empty:
                    return 0
                if "ID" in _df.columns:
                    _ids = _df["ID"].dropna()
                    _no_id = int(_df["ID"].isna().sum())
                    return int(_ids.nunique()) + _no_id
                return len(_df)

            def _r125_global_distinct(_frames, _id_col="ID") -> int:
                _non_empty = [f for f in _frames if isinstance(f, pd.DataFrame) and not f.empty]
                if not _non_empty:
                    return 0
                _combined = pd.concat(_non_empty, ignore_index=True)
                return _r125_distinct_id_count(_combined)

            summary_rows = []
            for cssm_name, data in team_data.items():
                # Round 10 / Phase 7.3: ``Num_Subscriptions`` previously
                # held ``len(data['subscriptions'])`` which is a row
                # count of the subscriptions DataFrame -- one customer
                # with five subscriptions counted as five.  That made
                # the Team_Summary sheet disagree with every customer-
                # level Word/Excel section that uses *distinct
                # customer counts*.  Add an explicit ``Num_Customers``
                # column derived from the deduped ``customers`` list
                # so the leader can compare like-for-like.
                _customers_list = data.get("customers", []) or []
                summary_rows.append(
                    {
                        "Team_Member": cssm_name,
                        "Num_Customers": len(_customers_list),
                        "Num_Subscriptions": len(data.get("subscriptions", pd.DataFrame())),
                        # Round 125 / D1: distinct-ID per-person counts.
                        "Num_Action_Plans": _r125_distinct_id_count(data.get("action_plans", pd.DataFrame())),
                        "Num_Adoption_Barriers": _r125_distinct_id_count(data.get("adoption_barriers", pd.DataFrame())),
                        "Num_Customer_Pulse": _r125_distinct_id_count(data.get("customer_pulse", pd.DataFrame())),
                        "Num_Success_Priorities": _r125_distinct_id_count(
                            data.get("success_priorities", pd.DataFrame())
                        ),
                        "Num_TAC_Cases": _r139_distinct_tac_count(data.get("tac_cases", pd.DataFrame())),
                        "Customers": ", ".join(_customers_list),
                    }
                )
            if summary_rows:
                # Round 125 / D1: append a deduped TOTAL row so the
                # per-person column foots to the cross-CSSM-deduped
                # headline (matches the deduped XLSX data sheets below).
                try:
                    _all_cust_total = sorted(
                        {_c for _d in team_data.values() for _c in (_d.get("customers", []) or []) if _c}
                    )
                    summary_rows.append(
                        {
                            "Team_Member": "TOTAL (deduped)",
                            "Num_Customers": len(_all_cust_total),
                            "Num_Subscriptions": _r125_global_distinct(
                                [_d.get("subscriptions", pd.DataFrame()) for _d in team_data.values()]
                            ),
                            "Num_Action_Plans": _r125_global_distinct(
                                [_d.get("action_plans", pd.DataFrame()) for _d in team_data.values()]
                            ),
                            "Num_Adoption_Barriers": _r125_global_distinct(
                                [_d.get("adoption_barriers", pd.DataFrame()) for _d in team_data.values()]
                            ),
                            "Num_Customer_Pulse": _r125_global_distinct(
                                [_d.get("customer_pulse", pd.DataFrame()) for _d in team_data.values()]
                            ),
                            "Num_Success_Priorities": _r125_global_distinct(
                                [_d.get("success_priorities", pd.DataFrame()) for _d in team_data.values()]
                            ),
                            "Num_TAC_Cases": _r139_distinct_tac_count(
                                pd.concat(
                                    [_d.get("tac_cases", pd.DataFrame()) for _d in team_data.values()],
                                    ignore_index=True,
                                )
                                if team_data
                                else pd.DataFrame()
                            ),
                            "Customers": f"{len(_all_cust_total)} distinct customers (cross-CSSM deduped)",
                        }
                    )
                except Exception as _r125_total_err:  # noqa: BLE001
                    logger.debug("Round 125 / D1: TOTAL row build skipped: %s", _r125_total_err)
                sheets["Team_Summary"] = pd.DataFrame(summary_rows)

            if all_action_plans:
                # Round 78 / B2: dedup AP by ID before XLSX write.
                # Build 53 audit caught Leader.Action_Plans carrying
                # 366 sheet rows / 344 unique IDs (22 duplicate AP rows)
                # for Brian Frazier 90d. Same root cause as R75/B2 (AB
                # sheet) but on the AP sheet: when a single Action Plan
                # is attributed to multiple CSSMs via the R72
                # ``_ATTRIBUTED_BY_ACCOUNT`` shared-account pathway in
                # ``_slice_by_owner_or_account``, per-CSSM AP frames
                # each carry the SAME ID, and this raw ``pd.concat``
                # emits the row N times (one per attributed CSSM).
                # Fix: drop_dup by ID with keep='first' so the row's
                # CSSM column is the first attribution -- matching the
                # order in which _slice_by_owner_or_account walked the
                # team_data. Rows without an ID column are passed
                # through unchanged. Mirrors R75/B2 (Adoption_Barriers).
                _r78_ap_combined = pd.concat(all_action_plans, ignore_index=True)
                if "ID" in _r78_ap_combined.columns:
                    _r78_ap_before = len(_r78_ap_combined)
                    _r78_ap_with_id = _r78_ap_combined[_r78_ap_combined["ID"].notna()].drop_duplicates(
                        subset=["ID"], keep="first"
                    )
                    _r78_ap_no_id = _r78_ap_combined[_r78_ap_combined["ID"].isna()]
                    _r78_ap_combined = pd.concat([_r78_ap_with_id, _r78_ap_no_id], ignore_index=True)
                    _r78_ap_after = len(_r78_ap_combined)
                    if _r78_ap_after != _r78_ap_before:
                        logger.info(
                            "Round 78 / B2: leader Action_Plans sheet "
                            "deduped by ID: %d raw rows -> %d unique "
                            "(removed %d cross-CSSM duplicates)",
                            _r78_ap_before,
                            _r78_ap_after,
                            _r78_ap_before - _r78_ap_after,
                        )
                sheets["Action_Plans"] = _r78_ap_combined
            if all_adoption_barriers:
                # Round 75 / B2: dedup by barrier ID before XLSX write.
                # Build 47 audit caught Leader.Adoption_Barriers carrying
                # 73 sheet rows / 69 unique IDs (4 duplicate barrier rows)
                # for Brian Frazier 90d. Root cause: when a single
                # adoption barrier is attributed to multiple CSSMs via
                # the R72 ``_ATTRIBUTED_BY_ACCOUNT`` shared-account
                # pathway in ``_slice_by_owner_or_account``, the
                # per-CSSM AB frames each carry the SAME ID, and this
                # raw ``pd.concat`` emits the row N times (one per
                # attributed CSSM). R72/Layer A already fixed the
                # canonical_metrics counts (so the docx headline reads
                # the deduplicated 65/63 figure) but the XLSX sheet
                # itself never went through the dedup. Fix: drop_dup
                # by ID with keep='first' so the row's CSSM column is
                # the first attribution -- matching the order in which
                # _slice_by_owner_or_account walked the team_data.
                # Rows without an ID column are passed through unchanged.
                _r75_ab_combined = pd.concat(all_adoption_barriers, ignore_index=True)
                if "ID" in _r75_ab_combined.columns:
                    _r75_ab_before = len(_r75_ab_combined)
                    _r75_ab_with_id = _r75_ab_combined[_r75_ab_combined["ID"].notna()].drop_duplicates(subset=['ID'], keep='first')
                    _r75_ab_no_id = _r75_ab_combined[_r75_ab_combined["ID"].isna()]
                    _r75_ab_combined = pd.concat([_r75_ab_with_id, _r75_ab_no_id], ignore_index=True)
                    _r75_ab_after = len(_r75_ab_combined)
                    if _r75_ab_after != _r75_ab_before:
                        logger.info(
                            "Round 75 / B2: leader Adoption_Barriers sheet "
                            "deduped by ID: %d raw rows -> %d unique "
                            "(removed %d cross-CSSM duplicates)",
                            _r75_ab_before,
                            _r75_ab_after,
                            _r75_ab_before - _r75_ab_after,
                        )
                sheets['Adoption_Barriers'] = _r75_ab_combined
            if all_customer_pulse:
                # Round 108 / artifact audit: mirror the AP/AB
                # cross-CSSM dedup contract for Customer Pulse. Shared
                # accounts can attribute the same Pulse row to more than
                # one CSSM, and the manager workbook should carry each
                # source ID once while keeping no-ID rows for forensics.
                _r108_cp_combined = pd.concat(all_customer_pulse, ignore_index=True)
                if "ID" in _r108_cp_combined.columns:
                    _r108_cp_before = len(_r108_cp_combined)
                    _r108_cp_with_id = _r108_cp_combined[_r108_cp_combined["ID"].notna()].drop_duplicates(
                        subset=["ID"], keep="first"
                    )
                    _r108_cp_no_id = _r108_cp_combined[_r108_cp_combined["ID"].isna()]
                    _r108_cp_combined = pd.concat([_r108_cp_with_id, _r108_cp_no_id], ignore_index=True)
                    _r108_cp_after = len(_r108_cp_combined)
                    if _r108_cp_after != _r108_cp_before:
                        logger.info(
                            "Round 108: leader Customer_Pulse sheet deduped "
                            "by ID: %d raw rows -> %d unique (removed %d "
                            "cross-CSSM duplicates)",
                            _r108_cp_before,
                            _r108_cp_after,
                            _r108_cp_before - _r108_cp_after,
                        )
                sheets["Customer_Pulse"] = _r108_cp_combined

            # Round 79 / Build 55 (B2/B3): Leader BE-priority sheets.
            # Wires the same orchestrator the Comprehensive flow uses so
            # the leader XLSX surfaces ``BE_Priority_Barriers`` and
            # ``BE_Focus_Areas`` for the manager's full team scope. The
            # scorer is deterministic (testable in isolation); the LLM
            # classifier optionally tags the top-50 with TRUE_BLOCKER /
            # TRAINING_GAP / FEATURE_REQUEST / DUPLICATE / AMBIGUOUS /
            # NOT_A_BARRIER but the tag NEVER alters the score. Honours
            # the R67/B2 always-assign contract via the inner pipeline
            # helper (any failure ships explicit provenance rows so the
            # operator never sees a phantom missing sheet).
            if "Adoption_Barriers" in sheets and not sheets["Adoption_Barriers"].empty:
                try:
                    import be_priority_pipeline as _r79_be_pipeline_lead  # noqa: PLC0415

                    _r79_lead_use_llm = bool(getattr(Config, "BE_PRIORITY_LLM_ENABLED", True))
                    _r79_lead_top_n = int(getattr(Config, "BE_PRIORITY_LLM_TOP_N", 50))
                    _r79_lead_focus_max = int(getattr(Config, "BE_PRIORITY_FOCUS_AREAS_PER_TECH", 10))
                    _r79_lead_focus_min = float(getattr(Config, "BE_PRIORITY_MIN_CLUSTER_SCORE", 30.0))

                    try:
                        from model_resolver import (
                            get_active_report_model as _r79_lead_get_report_model,
                        )

                        _r79_lead_report_model = _r79_lead_get_report_model()
                    except Exception:  # noqa: BLE001
                        _r79_lead_report_model = None

                    def _r79_lead_be_llm_callable(system_prompt: str, user_prompt: str) -> str:
                        return generate_llm_response(
                            system_prompt,
                            user_prompt,
                            model_name=_r79_lead_report_model,
                        )

                    _r79_lead_pulse_df = sheets.get("Customer_Pulse")

                    _r79_lead_barriers_df, _r79_lead_focus_df, _r79_lead_diag = (
                        _r79_be_pipeline_lead.build_be_priority_outputs(
                            sheets["Adoption_Barriers"],
                            risk_profiles=None,
                            pulse_df=_r79_lead_pulse_df,
                            llm_top_n=_r79_lead_top_n,
                            llm_callable=(_r79_lead_be_llm_callable if _r79_lead_use_llm else None),
                            use_llm=_r79_lead_use_llm,
                            max_per_tech=_r79_lead_focus_max,
                            min_cluster_score=_r79_lead_focus_min,
                            correlation_id=str(analysis_id),
                        )
                    )

                    sheets["BE_Priority_Barriers"] = _r79_lead_barriers_df
                    sheets["BE_Focus_Areas"] = _r79_lead_focus_df
                    status["be_priority_diag"] = _r79_lead_diag
                    logger.info(
                        "[LEADER] Round 79 / B2: BE-priority sheets built; rows_scored=%d top_n=%d focus_rows=%d",
                        int(_r79_lead_diag.get("rows_scored", 0) or 0),
                        int(_r79_lead_diag.get("top_n_selected", 0) or 0),
                        len(_r79_lead_focus_df) if _r79_lead_focus_df is not None else 0,
                    )
                except Exception as _r79_lead_err:  # noqa: BLE001
                    logger.warning(
                        "[LEADER] Round 79 / B2: BE-priority pipeline failed; emitting provenance rows: %s",
                        _r79_lead_err,
                    )
                    logger.debug(
                        "[LEADER] Round 79 / B2: full BE-priority pipeline trace: %s",
                        _r79_lead_err,
                        exc_info=True,
                    )
                    _r79_lead_msg = (
                        f"BE-priority pipeline raised: {str(_r79_lead_err)[:200]}. "
                        "Both sheets render with this provenance row so the "
                        "operator can root-cause without opening logs."
                    )
                    sheets["BE_Priority_Barriers"] = pd.DataFrame(
                        [
                            {
                                "_adoptiq_provenance_row": True,
                                "AdoptIQ_Status": "ERROR",
                                "AdoptIQ_Source": "be_priority_pipeline.build_be_priority_outputs",
                                "AdoptIQ_Message": _r79_lead_msg,
                            }
                        ]
                    )
                    sheets["BE_Focus_Areas"] = pd.DataFrame(
                        [
                            {
                                "_adoptiq_provenance_row": True,
                                "AdoptIQ_Status": "ERROR",
                                "AdoptIQ_Source": "be_priority_pipeline.build_be_priority_outputs",
                                "AdoptIQ_Message": _r79_lead_msg,
                            }
                        ]
                    )
            if all_success_priorities:
                sheets["Success_Priorities"] = pd.concat(all_success_priorities, ignore_index=True)
            if all_tac_cases:
                # Round 139 / Build 109: collapse TAC rows by case id before
                # the Leader XLSX write (mirrors R78/B2 AP dedup and the
                # canonical count helpers used by the parity gate).
                _r139_tac_combined = pd.concat(all_tac_cases, ignore_index=True)
                try:
                    from data_normalization import collapse_tac_cases as _r139_collapse_leader_tac

                    _r139_tac_collapsed = _r139_collapse_leader_tac(_r139_tac_combined)
                    if isinstance(_r139_tac_collapsed, pd.DataFrame) and not _r139_tac_collapsed.empty:
                        _r139_tac_before = len(_r139_tac_combined)
                        _r139_tac_combined = _r139_tac_collapsed
                        _r139_tac_after = len(_r139_tac_combined)
                        if _r139_tac_after != _r139_tac_before:
                            logger.info(
                                "Round 139 / Build 109: leader TAC_Cases sheet "
                                "collapsed by case id: %d raw rows -> %d unique",
                                _r139_tac_before,
                                _r139_tac_after,
                            )
                except Exception as _r139_tac_exc:  # noqa: BLE001
                    logger.debug(
                        "Round 139 / Build 109: leader TAC_Cases collapse skipped: %s",
                        _r139_tac_exc,
                        exc_info=False,
                    )
                sheets["TAC_Cases"] = _r139_tac_combined
            if all_subscriptions:
                sheets["Subscriptions"] = pd.concat(all_subscriptions, ignore_index=True)

            # Add external data if available (all data sources for Leader report)
            if ext_bugs:
                sheets["External_Bugs"] = pd.DataFrame(ext_bugs)
            if ext_incidents:
                sheets["External_Incidents"] = pd.DataFrame(ext_incidents)
            # Software defects (from CSOne/Adoption Barriers)
            if software_defects and software_defects.get("total_defects", 0) > 0:
                defect_rows = []
                for cust, ids in (software_defects.get("defect_by_customer") or {}).items():
                    # Round 5 / Phase 1.13: normalize customer name so leader
                    # Software_Defects rows match the same canonical name
                    # used by Customer_Pulse / Action_Plans / Subscriptions
                    # sheets and by report_consistency parity checks.
                    try:
                        _cust_norm = normalize_customer_name(cust) or cust
                    except Exception:
                        _cust_norm = cust
                    for did in ids if isinstance(ids, (list, set)) else [ids]:
                        defect_rows.append({"Customer": _cust_norm, "Defect_ID": did})
                if defect_rows:
                    sheets["Software_Defects"] = pd.DataFrame(defect_rows)
            # PSIRT vulnerabilities (from CSOne/Adoption Barriers)
            if psirt_vulns and psirt_vulns.get("total_vulnerabilities", 0) > 0:
                vuln_rows = []
                # Round 66 / Pass 2 (B9): per-customer rows MUST drop
                # NaN / blank / "Unknown" customer keys -- pre-R66 the
                # writer leaked rows with ``Customer=NaN`` (or empty
                # string from a malformed ``vulnerability_by_customer``
                # entry) into the PSIRT_Vulnerabilities XLSX sheet,
                # which downstream readers misread as "the vuln applies
                # to an unknown customer". Portfolio-wide CVE / PSIRT
                # advisories are still emitted below with the explicit
                # ``Customer = '(Portfolio-wide)'`` label so the
                # operator can tell "no customer attribution was
                # established" apart from "the writer dropped a row".
                for cust, ids in (psirt_vulns.get("vulnerability_by_customer") or {}).items():
                    # Round 5 / Phase 1.13: normalize customer name (see
                    # Software_Defects above).
                    try:
                        _cust_norm = normalize_customer_name(cust) or cust
                    except Exception:
                        _cust_norm = cust
                    # Round 66 / B9: skip blank / NaN / Unknown customer keys.
                    _cust_str = str(_cust_norm or "").strip()
                    if not _cust_str or _cust_str.lower() in {"nan", "none", "null", "unknown", "n/a"}:
                        continue
                    for vid in ids if isinstance(ids, (list, set)) else [ids]:
                        # Round 66 / B9: also skip empty vulnerability IDs.
                        _vid_str = str(vid or "").strip()
                        if not _vid_str or _vid_str.lower() in {"nan", "none"}:
                            continue
                        vuln_rows.append({"Customer": _cust_str, "Vulnerability_ID": _vid_str})
                # Portfolio-wide CVE / PSIRT advisories: label clearly
                # so a downstream reader cannot misread the empty-
                # Customer rows as "Unknown customer".
                for vid in psirt_vulns.get("cve_ids") or set():
                    _vid_str = str(vid or "").strip()
                    if not _vid_str or _vid_str.lower() in {"nan", "none"}:
                        continue
                    vuln_rows.append({"Customer": "(Portfolio-wide)", "Vulnerability_ID": _vid_str, "Type": "CVE"})
                for vid in psirt_vulns.get("psirt_advisories") or set():
                    _vid_str = str(vid or "").strip()
                    if not _vid_str or _vid_str.lower() in {"nan", "none"}:
                        continue
                    vuln_rows.append({"Customer": "(Portfolio-wide)", "Vulnerability_ID": _vid_str, "Type": "PSIRT"})
                if vuln_rows:
                    sheets["PSIRT_Vulnerabilities"] = pd.DataFrame(vuln_rows)

            # The paired Source Data File contains only the canonical,
            # content-digested sheets built from the same Word fact bundle.
            from decision_report_delivery import (  # noqa: PLC0415
                build_report_facts as _r142_build_leader_facts,
                build_source_data_sheets as _r142_build_leader_sheets,
                fact_contract_fingerprint as _r142_leader_fingerprint,
                source_data_path_for_word as _r142_leader_source_path,
                validate_cross_artifact_contract as _r142_validate_leader_contract,
                validate_written_source_workbook as _r142_validate_leader_workbook,
                write_source_data_workbook as _r142_write_leader_workbook,
            )
            from docx import Document as _r142_LeaderDocument  # noqa: PLC0415

            _r142_leader_facts = _r142_build_leader_facts(
                team_data,
                report_type="Leader",
                scope_type=scope_selection.scope_type,
                scope_value=scope_selection.display_value,
                manager_name=manager,
                technology=_r142_leader_technology,
                days=days,
                as_of=_r142_leader_as_of,
                data_as_of_utc=_r161_leader_freshness.get("data_as_of_utc") or "",
                data_as_of_state=_r161_leader_freshness.get("data_as_of_state") or "unavailable",
                data_as_of_detail=_r161_leader_freshness.get("data_as_of_detail") or "",
                retrieval_attempted_at_utc=_r161_leader_freshness.get("retrieval_attempted_at") or "",
                external_incidents=(ext_incidents if _r142_leader_external_sources_available else None),
                external_bugs=(ext_bugs if _r142_leader_external_sources_available else None),
                partial_data_warnings=_r30_leader_partial_warnings,
            )
            _r142_leader_source_sheets = _r142_build_leader_sheets(
                _r142_leader_facts,
            )
            status["data_as_of_utc"] = _r142_leader_facts.get("as_of_utc") or ""
            status["fact_fingerprint"] = _r142_leader_fingerprint(
                _r142_leader_facts,
            )
            _r142_leader_doc = _r142_LeaderDocument(filepath)
            _r142_leader_contract = _r142_validate_leader_contract(
                _r142_leader_facts,
                _r142_leader_source_sheets,
                _r142_leader_doc,
            )
            if not _r142_leader_contract.get("ok"):
                raise ValueError(
                    "Round 142 Leader delivery contract failed before Source Data write: "
                    + "; ".join(_r142_leader_contract.get("errors") or [])
                )
            excel_path = _r142_write_leader_workbook(
                _r142_leader_source_path(filepath),
                _r142_leader_source_sheets,
            )
            _r142_leader_written_contract = _r142_validate_leader_workbook(
                excel_path,
                _r142_leader_facts,
            )
            if not _r142_leader_written_contract.get("ok"):
                raise ValueError(
                    "Round 142 written Leader Source Data contract failed: "
                    + "; ".join(_r142_leader_written_contract.get("errors") or [])
                )
            status["delivery_contract"] = _r142_leader_contract
            status["source_data_contract"] = _r142_leader_written_contract
            _r142_leader_canonical_written = True
            logger.info(
                "[[OK]] Canonical Leader Source Data File created with %d sheets: %s",
                len(_r142_leader_source_sheets),
                excel_path,
            )

            # Legacy writer is retained only as a compatibility fallback for
            # an explicitly disabled concise contract.
            if sheets and not _r142_leader_canonical_written:
                logger.info(f"[[WRITE]] Writing Excel file with {len(sheets)} sheets: {list(sheets.keys())}")
                sheets_written = 0
                # Round 4 / Phase 1.1: initialize the failed-sheets
                # ledger BEFORE the writer context so the
                # ``Report_Info`` write at the end of the context
                # still has scope. The previous code initialized
                # this inside the ``except sheet_error`` branch
                # via ``locals().get('_failed_sheets') or []`` and
                # then tried to write ``Report_Info`` *after* the
                # ``with`` block exited — which closed the writer
                # and silently dropped the partial-completion
                # ledger.
                _failed_sheets: list = []
                # Round 70 / Phase 3 (#10): HTML strip the rich-text
                # Snowflake / CSOne sheets BEFORE the writer iterates
                # them. Build 43 acceptance audit found 1 cell in
                # ``External_Incidents`` with raw
                # ``<font size="3"><strong>...</strong></font><br />``
                # markup AND 1 cell in ``TAC_Cases`` with the same
                # ``persona : Admin\nOrgType : Customer ...`` HTML
                # entity leakage as CSOne_Detail_All. Mirror the
                # Comprehensive ``write_excel_workbook`` allow-list
                # behavior here so the Leader XLSX gets parity.
                _r70_leader_html_sheets = (
                    "TAC_Cases",
                    "External_Incidents",
                    "Adoption_Barriers",
                    "Customer_Pulse",
                    "Success_Priorities",
                    "Action_Plans",
                )
                try:
                    from data_normalization import strip_html_from_dataframe as _r70_strip_html_lead

                    for _r70_sn, _r70_sdf in list(sheets.items()):
                        if (
                            _r70_sn in _r70_leader_html_sheets
                            and isinstance(_r70_sdf, pd.DataFrame)
                            and not _r70_sdf.empty
                        ):
                            try:
                                sheets[_r70_sn] = _r70_strip_html_lead(_r70_sdf)
                            except Exception as _r70_strip_err:
                                logger.debug(
                                    "Round 70 / #10: HTML strip skipped for leader sheet %s: %s",
                                    _r70_sn,
                                    _r70_strip_err,
                                )
                except Exception as _r70_strip_import_err:
                    logger.debug("Round 70 / #10: leader HTML strip helper unavailable: %s", _r70_strip_import_err)

                with pd.ExcelWriter(excel_path, engine="xlsxwriter") as writer:
                    workbook = writer.book
                    # Round 16 / Phase 5.1: shared Table-name registry for
                    # the Round-15 polish helper.
                    _r16_used_table_names: set = set()

                    # Create formats
                    header_format = workbook.add_format(
                        {
                            "bold": True,
                            "text_wrap": True,
                            "valign": "top",
                            "fg_color": "#4472C4",
                            "font_color": "white",
                            "border": 1,
                            "font_size": 11,
                        }
                    )

                    title_format = workbook.add_format(
                        {
                            "bold": True,
                            "font_size": 16,
                            "fg_color": "#2F4F4F",
                            "font_color": "white",
                            "border": 1,
                            "align": "center",
                            "valign": "vcenter",
                        }
                    )

                    # Round 65 / R-1: collect per-sheet titles to enrich
                    # the Report_Info sheet.  Build 37 audit found that
                    # writing a merged title row in row 0 of every data
                    # sheet broke downstream pd.read_excel consumers
                    # (column headers landed in row 1, so the parsed
                    # column names were the title strings).
                    _r65_leader_sheet_titles: list[tuple[str, str]] = []

                    for sheet_name, df in sheets.items():
                        # Round 2 / Phase 2.1: surface fetch_error
                        # tristate so a failed fetch is rendered as
                        # ``Data_Unavailable`` rather than dropped to a
                        # silent zero-row sheet.
                        _fetch_error = None
                        _fetch_error_kind = None
                        try:
                            _fetch_error = df.attrs.get("fetch_error") if hasattr(df, "attrs") else None
                            _fetch_error_kind = df.attrs.get("fetch_error_kind") if hasattr(df, "attrs") else None
                        except Exception:
                            _fetch_error = None
                        if _fetch_error:
                            try:
                                unavailable_df = pd.DataFrame(
                                    [
                                        {
                                            "Status": "Data Unavailable",
                                            "Dataset": sheet_name,
                                            "Reason": str(_fetch_error_kind or "fetch_error"),
                                            "Detail": str(_fetch_error)[:512],
                                            "Generated_At": datetime.now(timezone.utc).strftime(
                                                "%Y-%m-%d %H:%M:%S UTC"
                                            ),
                                        }
                                    ]
                                )
                                # Round 65 / R-1: clean schema (header in row 0).
                                unavailable_df.to_excel(writer, sheet_name=sheet_name, index=False, startrow=0)
                                _r65_leader_sheet_titles.append(
                                    (sheet_name, f"{sheet_name.replace('_', ' ')} — Data Unavailable")
                                )
                                sheets_written += 1
                                logger.warning(
                                    f"[LEADER EXCEL] Sheet '{sheet_name}' rendered as Data_Unavailable: {_fetch_error}"
                                )
                            except Exception as _du_err:
                                logger.error(
                                    f"[LEADER EXCEL] Failed to write Data_Unavailable for '{sheet_name}': {_du_err}"
                                )
                            continue
                        if not df.empty:
                            try:
                                # Clean datetime columns for Excel compatibility
                                df_clean = _clean_datetime_columns_for_excel(df)

                                # Round 15 / Phase 1.5: leader-team-report
                                # writer also routes through the SSoT.
                                try:
                                    df_clean = _r15_apply_export_schema(df_clean, sheet_name=sheet_name)
                                except Exception as _schema_err:
                                    logger.debug(
                                        "Round 15 export schema skipped for sheet '%s': %s",
                                        sheet_name,
                                        _schema_err,
                                    )

                                # Round 65 / R-1: header in row 0, no
                                # merged title row above (Build 37 audit).
                                df_clean.to_excel(writer, sheet_name=sheet_name, index=False, startrow=0)

                                # Format worksheet
                                worksheet = writer.sheets[sheet_name]

                                # Round 16 / Phase 5.1: layer Round-15
                                # polish (Excel Table + conditional
                                # formatting) on the leader-team-report
                                # sheets.  Helper is internally
                                # defensive; we wrap it once more so a
                                # truly unexpected failure cannot
                                # cascade into a partial workbook.
                                try:
                                    _r16_apply_excel_polish(
                                        workbook,
                                        worksheet,
                                        df_clean,
                                        sheet_name,
                                        _r16_used_table_names,
                                        startrow=0,
                                    )
                                except Exception as _r16_err:
                                    logger.warning(
                                        "Round 16 / Phase 5.1: apply_excel_polish skipped on '%s': %s",
                                        sheet_name,
                                        _r16_err,
                                    )

                                # Round 65 / R-1: capture the legacy
                                # title for Report_Info (drop the merged
                                # title row write at row 0).
                                title_text = f"{sheet_name.replace('_', ' ')} - {manager} Team Report"
                                _r65_leader_sheet_titles.append((sheet_name, title_text))

                                # Format headers (overwrite pd.to_excel
                                # default at row 0 with branded format).
                                for col_num, value in enumerate(df_clean.columns.values):
                                    worksheet.write(0, col_num, value, header_format)

                                # Auto-adjust column widths (guard against NaN from empty columns)
                                for i, col in enumerate(df_clean.columns):
                                    try:
                                        content_max = df_clean[col].astype(str).map(len).max()
                                        content_max = content_max if pd.notna(content_max) else 0
                                    except (ValueError, TypeError):
                                        content_max = 0
                                    max_length = max(content_max, len(str(col)))
                                    worksheet.set_column(i, i, min(max_length + 2, 50))

                                sheets_written += 1
                            except Exception as sheet_error:
                                # Round 2 / Phase 2.7: track per-sheet
                                # write failures so the final
                                # ``Report_Info`` sheet can list them
                                # and downstream consumers can tell
                                # "0 rows" from "write threw".
                                logger.warning(f"[[WARNING]] Failed to write sheet '{sheet_name}': {sheet_error}")
                                _failed_sheets.append(
                                    {
                                        "sheet": sheet_name,
                                        "error": str(sheet_error)[:512],
                                    }
                                )

                    # Round 5 / Phase 1.7: always write Report_Info with
                    # the run metadata (manager / days / analysis_id /
                    # generated_at_UTC), partial_data_warnings ledger,
                    # and per-sheet failure ledger.  Round 4 only wrote
                    # this when ``_failed_sheets`` was non-empty; that
                    # silently dropped the partial_data_warnings + meta
                    # context whenever every sheet wrote successfully.
                    try:
                        _leader_pdw = []
                        try:
                            _ldr_status = (
                                analysis_status.get(analysis_id, {}) if isinstance(analysis_status, dict) else {}
                            )
                            _src = _ldr_status.get("partial_data_warnings") or []
                            if isinstance(_src, list):
                                _leader_pdw = _src
                        except Exception:
                            _leader_pdw = []
                        # Round 73 / Phase 3 (F6): standardize Leader Report_Info on
                        # the canonical ``Item`` first-column header (was ``Field`` pre-R73).
                        # Leader keeps its 4-column legacy schema (``Item / Value / Detail
                        # / Generated_At``) -- the 4-col shape carries per-row Detail and
                        # Generated_At slots the other writers don't need -- but the
                        # FIRST TWO columns are now the canonical ``Item / Value``
                        # subset so a downstream consumer running
                        # ``pd.read_excel("Report_Info")[["Item", "Value"]]`` gets the
                        # same projection as Compact / Renewal / Comprehensive.
                        _info_rows = [
                            {
                                "Item": "Status",
                                "Value": "PARTIAL" if _failed_sheets else "OK",
                                "Detail": "",
                                "Generated_At": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC"),
                            },
                            {"Item": "Manager", "Value": str(manager or "n/a"), "Detail": "", "Generated_At": ""},
                            {"Item": "Days", "Value": str(days), "Detail": "", "Generated_At": ""},
                            {"Item": "Analysis_Id", "Value": str(analysis_id), "Detail": "", "Generated_At": ""},
                            # Round 39 / Phase 4.5: count Report_Info
                            # itself as a written sheet so this field
                            # matches the actual workbook tab count.
                            # Pre-Round-39 the value was the count of
                            # data sheets BEFORE Report_Info was
                            # written, so a workbook with 11 tabs
                            # advertised "Sheets_Written = 10".
                            {
                                "Item": "Sheets_Written",
                                "Value": str(sheets_written + 1),
                                "Detail": "",
                                "Generated_At": "",
                            },
                            {
                                "Item": "Partial_Data_Warning_Count",
                                "Value": str(len(_leader_pdw)),
                                "Detail": "",
                                "Generated_At": "",
                            },
                        ]
                        # Round 68 / Build 42 (A1): build label so the
                        # Leader XLSX carries the canonical version /
                        # build / process-start / generated-at rows.
                        try:
                            from _r68_build_label import append_build_label_records_4col as _r68_append_4col  # noqa: PLC0415

                            _r68_append_4col(_info_rows)
                        except Exception as _r68_err:  # noqa: BLE001
                            logger.debug("Round 68 / A1: Leader build label skipped: %s", _r68_err)
                        # Round 110 / Build 79 (latent-bug fix): the partial-warning
                        # and failed-sheet append blocks below previously used
                        # ``'Field':`` as the first-column key while every other
                        # row in this block uses ``'Item':`` (R73 / Phase 3 / F6).
                        # ``pd.DataFrame(_info_rows)`` builds the union of all dict
                        # keys so any partial warning OR failed sheet would silently
                        # add a stray fifth ``Field`` column with NaN on every other
                        # row, violating R73/F6's "first two columns are the
                        # canonical Item / Value subset" promise. Today's clean
                        # Build 78 cohort did not trip the bug because Brian
                        # Frazier's run had ``Partial_Data_Warning_Count=0`` AND
                        # ``_failed_sheets=[]``; Build 79 normalises both branches
                        # onto the canonical ``'Item':`` key so the four-column
                        # schema holds in every Leader run.
                        for _i, _w in enumerate(_leader_pdw, 1):
                            try:
                                _ds = (_w.get("dataset") if isinstance(_w, dict) else None) or "n/a"
                                _kind = (_w.get("kind") if isinstance(_w, dict) else None) or "n/a"
                                _err = _w.get("error") if isinstance(_w, dict) else str(_w)
                                _info_rows.append(
                                    {
                                        'Item': f'Partial_Data_Warning_{_i}',  # Round 110: was 'Field' (R73/F6 schema parity)
                                        "Value": _ds,
                                        "Detail": f"{_kind}: {str(_err)[:200]}",
                                        "Generated_At": "",
                                    }
                                )
                            except Exception:
                                continue
                        for fs in _failed_sheets:
                            _info_rows.append(
                                {
                                    'Item': 'Failed_Sheet',  # Round 110: was 'Field' (R73/F6 schema parity)
                                    "Value": fs["sheet"],
                                    "Detail": fs["error"],
                                    "Generated_At": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC"),
                                }
                            )
                        # Round 65 / R-1: surface the per-sheet titles
                        # that previously lived in row 0 of each data
                        # sheet so the branded context survives even
                        # though data sheets now carry a clean header in
                        # row 0 (consumable via pd.read_excel).
                        for _ldr_sn, _ldr_tt in _r65_leader_sheet_titles:
                            _info_rows.append(
                                {
                                    "Item": f"Sheet_Title:{_ldr_sn}",
                                    "Value": _ldr_tt,
                                    "Detail": "",
                                    "Generated_At": "",
                                }
                            )
                        report_info_df = pd.DataFrame(_info_rows)
                        report_info_df.to_excel(writer, sheet_name="Report_Info", index=False)
                    except Exception as _ri_err:
                        logger.error(f"[LEADER EXCEL] Failed to write Report_Info: {_ri_err}")

                if sheets_written > 0 and not _failed_sheets:
                    logger.info(f"[[OK]] Excel file created successfully ({sheets_written} sheets): {excel_path}")
                elif sheets_written > 0 and _failed_sheets:
                    # Workbook is PARTIAL — log loudly so the request
                    # path can flag it instead of advertising it as
                    # success.  We still keep the file so the user
                    # gets the sheets that did write, but we expose
                    # the ledger via ``Report_Info``.
                    logger.error(
                        f"[[PARTIAL]] Excel file created with {sheets_written} sheets and "
                        f"{len(_failed_sheets)} failed sheets: {excel_path}; failed: "
                        f"{[f['sheet'] for f in _failed_sheets]}"
                    )
                else:
                    logger.error(f"[[ERROR]] All sheets failed to write, removing empty Excel file")
                    try:
                        os.remove(excel_path)
                    except OSError:
                        pass
                    excel_path = None
            elif not _r142_leader_canonical_written:
                logger.warning(
                    f"[[WARNING]] No team data available for Excel (team_data keys: {list(team_data.keys())})"
                )
                excel_path = None

        except Exception as excel_error:
            logger.error(f"[[ERROR]] Error creating Excel file: {excel_error}", exc_info=True)
            raise

        # Round 148: the canonical Leader artifact is the concise decision
        # report. Additional BE tables are not represented in its exact
        # visible-facts contract, so keep their source AB evidence in the
        # paired workbook and reserve the legacy append for an explicitly
        # disabled concise contract.
        _r142_leader_concise_default = True

        # Round 79 / Build 55 (B5): append the BE Priority Focus Areas
        # Word section to the leader docx as a POST-PROCESSING step --
        # the leader doc is built+saved inside ``generate_leader_report``
        # so we re-open the file, append the section, and save back.
        # This keeps ``leader_report_generator`` unchanged (less risk)
        # while still giving the operator the same prose section the
        # Comprehensive flow injects via ``add_be_priority_focus_areas_section``
        # in-line. The section is appended BEFORE the R57 citation
        # injector runs so any [Source: ...] markers we emit get
        # processed by the same chrome path. Failures log + continue;
        # the XLSX still carries the canonical data via
        # ``BE_Priority_Barriers`` / ``BE_Focus_Areas``. Pinned by
        # ``tests/test_round79_b5_be_word_section.py``.
        try:
            import be_priority_word_section as _r79_lead_be_word  # noqa: PLC0415
            from docx import Document as _r79_lead_DocxDocument  # noqa: PLC0415

            # Round 79 / Build 55 (R20-001): ``sheets`` is reliably bound at
            # line 26597 (unconditional ``sheets = {}`` inside the leader
            # generation block). The outer try/except still catches any
            # unexpected ``NameError`` so a future refactor that hoists this
            # block above the binding does not silently skip the section.
            _r79_lead_barriers = sheets.get("BE_Priority_Barriers") if isinstance(sheets, dict) else None
            _r79_lead_focus = sheets.get("BE_Focus_Areas") if isinstance(sheets, dict) else None
            _r79_lead_word_diag = status.get("be_priority_diag")
            # Round 145: Leader is the concise manager-facing artifact. A
            # provenance-only BE frame carries no decision or focus area, so
            # do not spend a mostly blank final page repeating threshold
            # guidance. The provenance row remains in Source Data; real focus
            # areas still render here.
            _r145_has_leader_be_focus = _r79_lead_focus is not None and not _r79_lead_be_word._is_provenance_only(
                _r79_lead_focus
            )
            if (
                not _r142_leader_concise_default
                and _r145_has_leader_be_focus
                and filepath
            ):
                _r79_lead_doc = _r79_lead_DocxDocument(filepath)
                _r79_lead_be_word.add_be_priority_focus_areas_section(
                    _r79_lead_doc,
                    barriers_df=_r79_lead_barriers,
                    focus_areas_df=_r79_lead_focus,
                    diag=_r79_lead_word_diag,
                    heading_level=2,
                )
                _r79_lead_doc.save(filepath)
                logger.info(
                    "[LEADER] Round 79 / B5: BE-priority Word section appended to %s",
                    filepath,
                )
            elif _r142_leader_concise_default and filepath:
                logger.info(
                    "[LEADER] Round 148: BE-priority source evidence retained "
                    "in the paired workbook and omitted from the concise Word contract"
                )
            elif filepath:
                logger.info(
                    "[LEADER] Round 145: provenance-only BE-priority detail "
                    "retained in Source Data and omitted from concise Word output"
                )
        except Exception as _r79_lead_word_err:  # noqa: BLE001
            logger.warning(
                "[LEADER] Round 79 / B5: BE-priority Word section skipped: %s",
                _r79_lead_word_err,
            )
            logger.debug(
                "[LEADER] Round 79 / B5: full BE-priority Word section trace: %s",
                _r79_lead_word_err,
                exc_info=True,
            )

        # Round 57 / Phase B: inject [Source: ...] citations into the
        # leader .docx before status flips to completed.  Leader carries
        # 408 metric claims and 745 uncited paragraphs in the Phase 3.5
        # baseline -- by far the largest surface; the injector walks
        # them all in one pass and writes back atomically.
        if not _r142_leader_concise_default:
            _r57_inject_citations_safe(filepath, scenario_key="leader")
        # Round 74 / Phase 1 (F1): defense-in-depth post-save footer
        # enforcement -- see compact path above for the full rationale.
        _r74_enforce_footer_safe(filepath, scenario_key="leader")

        # Reopen after every Word mutation and block completion unless the
        # concise budget, chart presence, and paired Source Data facts still
        # reconcile.
        from docx import Document as _r142_FinalLeaderDocument  # noqa: PLC0415

        _r142_final_leader_doc = _r142_FinalLeaderDocument(filepath)
        _r142_final_leader_contract = _r142_validate_leader_contract(
            _r142_leader_facts,
            _r142_leader_source_sheets,
            _r142_final_leader_doc,
        )
        if not _r142_final_leader_contract.get("ok"):
            raise ValueError(
                "Round 142 final Leader delivery contract failed: "
                + "; ".join(_r142_final_leader_contract.get("errors") or [])
            )
        status["delivery_contract"] = _r142_final_leader_contract

        with analysis_status_lock:
            _update_progress(status, 100, "Leader report generated successfully!", "Complete")
            status["status"] = "completed"
            status["completion_time"] = _now_utc_iso_z()
            completion_time = status["completion_time"]
            report_type = status.get("report_type", "leader")
            manager = status.get("manager", "")
            technology = status.get("technology", status.get("tech", ""))
            customer_name = status.get("customer_name", "")
            start_time = status.get("start_time", "")
            insights_payload = _build_insights_payload(status, "Leader report completed")
            status["word_report"] = filepath
            status["excel_report"] = excel_path if excel_path else None
            status["source_data_report"] = excel_path if excel_path else None
            status["results"] = {
                "word_report": filepath,
                "excel_report": excel_path if excel_path else None,
                "source_data_report": excel_path if excel_path else None,
                "success_message": success_msg,
            }
            status["analysis_id"] = analysis_id  # Round 92
            _r92_write_corpus_sidecars(status)  # Round 92
            # Round 5 / Phase 6.7: persist *under* the lock so the on-disk
            # JSON snapshot matches the in-memory completion state.  See
            # the matching comment in the compact-report worker.
            save_analysis_status()

        # Round 139 / Build 109: record completion before audit so history has artifact paths.
        record_report_completion(
            analysis_id,
            report_type,
            manager,
            technology,
            customer_name,
            "completed",
            start_time,
            completion_time,
            days=status.get("days") if isinstance(status, dict) else None,
            word_path=filepath if "filepath" in locals() and filepath else "",
            excel_path=excel_path if "excel_path" in locals() and excel_path else "",
            **_r146_report_history_scope(status),
        )
        auto_audit_report(analysis_id)
        try:
            store_report_insights(analysis_id, report_type, manager, technology, customer_name, insights_payload)
        except Exception as _si_err:
            logger.warning(f"store_report_insights failed: {_si_err}")

        logger.info(f"[[OK]] Leader report completed: {analysis_id}")

    except Exception as e:
        import traceback

        error_traceback = traceback.format_exc()
        logger.error(f" Leader report generation failed: {e}", exc_info=True)
        logger.error(f"[[SEARCH]] DEBUG: Full traceback:\n{error_traceback}")

        # Round 152 / A4: the Leader worker persisted only a fixed sentence --
        # no ``error_kind``, no ``error_detail``, no traceback -- so a failed
        # Leader run was the least diagnosable of the five report paths even
        # though it is the manager's primary artifact.  Route it through the
        # shared, scrubbed recorder like the others.
        _r152_failure = _record_worker_failure(
            analysis_id,
            e,
            fallback_message="Leader report generation failed. Please check the Admin page for details.",
            traceback_text=error_traceback[:8000],
        )
        logger.error(f"[[ERROR]] Leader report failed (kind={_r152_failure.get('error_kind')})")
        with analysis_status_lock:
            if analysis_id not in analysis_status:
                analysis_status[analysis_id] = {}
            analysis_status[analysis_id]["message"] = "Error during leader report generation"
            # Round 5 / Phase 6.9: a failed run has an *end* time, not a
            # *completion* time -- callers (History page, admin tile)
            # use the presence of ``completion_time`` as a soft signal
            # that the artifact is downloadable, so leaving it set on
            # the failure path made failed leader reports show up next
            # to successful ones in some surfaces.  Use ``end_time``
            # instead and stop populating ``completion_time`` for the
            # failure path.
            analysis_status[analysis_id]["end_time"] = _now_utc_iso_z()
            save_analysis_status()
    finally:
        if ctx:
            try:
                ctx.close()
                logger.info(f"[[CLEANUP]] Database connection closed for leader report")
            except Exception as close_err:
                logger.warning(f"[[WARNING]] Error closing database connection: {close_err}")
        with cancellation_flags_lock:
            cancellation_flags.pop(analysis_id, None)


@app.route("/api/leader_scope_options", methods=["GET"])
def leader_scope_options():
    """Return roster-backed members and available scoped customers.

    Round 142: this endpoint is read-only. Member options come exclusively
    from ``TEAM_ROSTER``; customer options come from subscriptions fetched for
    that manager (or one validated direct report). When Snowflake is not
    reachable the roster remains usable and the response degrades honestly.
    """
    manager = str(request.args.get("manager", "") or "").strip()
    member_email = str(request.args.get("member_email", "") or "").strip()
    include_customers = (
        str(request.args.get("include_customers", "") or "").strip().lower() in {"1", "true", "yes"}
        or str(request.args.get("scope_type", "") or "").strip().lower() == "customer"
    )
    payload, status_code = _r146_leader_scope_options_payload(
        manager,
        member_email=member_email,
        include_customers=include_customers,
    )
    return jsonify(payload), status_code


def _r146_leader_scope_options_payload(
    manager: str,
    *,
    member_email: str = "",
    include_customers: bool = False,
) -> tuple[dict, int]:
    """Round 146: shared, fail-closed Leader scope option contract."""
    is_valid_manager, manager_error = validate_manager_input(manager)
    if not is_valid_manager:
        return {"success": False, "error": manager_error}, 400

    try:
        team_selection = validate_leader_scope_request(manager, "team", "", TEAM_ROSTER)
        member_selection = None
        if member_email:
            member_selection = validate_leader_scope_request(manager, "member", member_email, TEAM_ROSTER)
    except LeaderScopeValidationError as scope_error:
        return {"success": False, "error": str(scope_error)}, 400

    members = manager_roster_members(TEAM_ROSTER, team_selection.manager_name)
    if not members:
        return {
            "success": False,
            "error": "The selected manager does not have any members in the Leader roster.",
        }, 400
    payload = {
        "success": True,
        "manager": team_selection.manager_name,
        "members": members,
        "customers": [],
        "customers_available": False,
        "warning": "",
    }
    if not include_customers:
        return payload, 200

    ctx = None
    try:
        ctx = _connect_with_keeper()
        # Fetch the manager-wide frame even for a selected member. The shared
        # helper needs that full authorized universe to reject account ids
        # that span multiple customers before offering an unsafe option.
        emails = [member["email"] for member in members]
        subscriptions_df = get_subscriptions_for_team(ctx, emails)
        option_subscriptions = subscriptions_df
        if member_selection is not None:
            option_subscriptions = filter_leader_subscriptions(subscriptions_df, member_selection)
        candidate_options = leader_customer_options(option_subscriptions)
        safe_options = []
        excluded_ambiguous = 0
        for option in candidate_options:
            try:
                candidate_selection = validate_leader_scope_request(
                    team_selection.manager_name,
                    "customer",
                    str(option.get("value") or ""),
                    TEAM_ROSTER,
                    member_email=(member_selection.member_email if member_selection is not None else ""),
                )
                filter_leader_subscriptions(subscriptions_df, candidate_selection)
                safe_options.append(option)
            except LeaderScopeValidationError:
                excluded_ambiguous += 1
        payload["customers"] = safe_options
        payload["customers_available"] = True
        if excluded_ambiguous:
            payload["warning"] = (
                f"{excluded_ambiguous} customer option(s) were omitted because "
                "their shared account identifiers cannot be isolated accurately."
            )
    except Exception as options_error:  # noqa: BLE001 - optional live lookup
        logger.warning(
            "Round 142: Leader customer options unavailable for %s (%s)",
            team_selection.manager_name,
            type(options_error).__name__,
        )
        payload["warning"] = (
            "Customer options are unavailable because subscription data "
            "could not be reached. Team and member scopes are still available."
        )
    finally:
        if ctx is not None:
            try:
                ctx.close()
            except Exception:
                pass
    return payload, 200


def _r146_status_for_workspace(analysis_id: str) -> Optional[dict]:
    """Resolve one run from memory, persisted status, or durable history."""
    if not _is_valid_analysis_id(analysis_id):
        return None
    with analysis_status_lock:
        current = analysis_status.get(analysis_id)
        if isinstance(current, dict):
            status = dict(current)
            status.setdefault("analysis_id", analysis_id)
            return status
    try:
        status_file_path = str(_APP_SUPPORT / STATUS_FILE) if not os.path.isabs(STATUS_FILE) else STATUS_FILE
        if os.path.isfile(status_file_path) and os.path.getsize(status_file_path) <= 20 * 1024 * 1024:
            with open(status_file_path, "r", encoding="utf-8") as status_handle:
                persisted = json.load(status_handle)
            status = persisted.get(analysis_id) if isinstance(persisted, dict) else None
            if isinstance(status, dict):
                status = _hydrate_status_datetimes(status)
                status["analysis_id"] = analysis_id
                return status
    except Exception as status_error:  # noqa: BLE001 - durable fallback below
        logger.debug(
            "Round 146: persisted workspace status lookup failed (%s)",
            type(status_error).__name__,
        )
    status = _build_status_from_report_history(analysis_id)
    if isinstance(status, dict):
        status["analysis_id"] = analysis_id
        return status
    return None


def _r146_workspace_artifact(status: dict, kind: str) -> Optional[str]:
    keys = ("excel_report", "excel_path") if kind == "excel" else ("word_report", "report_path", "word_path")
    raw_path = next((status.get(key) for key in keys if status.get(key)), None)
    if not raw_path and isinstance(status.get("results"), dict):
        result_key = "excel_report" if kind == "excel" else "word_report"
        raw_path = status["results"].get(result_key)
    resolved = _r92_resolve_output_artifact(raw_path) if raw_path else None
    expected_suffix = ".xlsx" if kind == "excel" else ".docx"
    if not resolved or Path(resolved).suffix.casefold() != expected_suffix:
        return None
    return resolved


def _r146_persisted_excel_hash(analysis_id: str, status: dict) -> str:
    """Return the audit-owned Excel hash when one was recorded for the run."""
    expected_hash = str(status.get("excel_hash") or "").strip().casefold()
    if expected_hash or status.get("_rehydrated_from_audit"):
        return expected_hash
    persisted = _build_status_from_report_history(analysis_id)
    if isinstance(persisted, dict):
        return str(persisted.get("excel_hash") or "").strip().casefold()
    return ""


def _r146_file_sha256(path: str) -> str:
    """Hash the current artifact bytes without caching filesystem state."""
    import hashlib

    digest = hashlib.sha256()
    with open(path, "rb") as artifact_handle:
        for chunk in iter(lambda: artifact_handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _r147_exact_artifact_hash_verified(
    analysis_id: str,
    expected_hash: str,
    excel_path: str,
) -> bool:
    """Require an audit-owned SHA-256 proof for exact evidence operations.

    Legacy workspace viewing intentionally remains compatible with report rows
    that predate persisted hashes.  Exact evidence and report-bound Ask AI are
    stricter: an absent or malformed persisted digest is not independent proof
    of the artifact bytes and therefore fails closed.
    """

    expected = str(expected_hash or "").strip().casefold()
    if not re.fullmatch(r"[0-9a-f]{64}", expected):
        logger.warning(
            "Round 147: exact artifact missing valid persisted hash aid_digest=%s",
            _id_digest(analysis_id),
        )
        return False
    try:
        actual = _r146_file_sha256(excel_path)
    except Exception as hash_error:  # noqa: BLE001 - exact operations fail closed
        logger.warning(
            "Round 147: exact artifact hashing failed aid_digest=%s kind=%s",
            _id_digest(analysis_id),
            type(hash_error).__name__,
        )
        return False
    verified = secrets.compare_digest(expected, actual)
    if not verified:
        logger.warning(
            "Round 147: exact artifact hash mismatch aid_digest=%s",
            _id_digest(analysis_id),
        )
    return verified


def _r146_workbook_hash_verified(
    analysis_id: str,
    expected_hash: str,
    excel_path: str,
    workbook: dict,
) -> bool:
    """Verify a recorded audit hash against both current bytes and parsed input."""
    if not expected_hash:
        # Older report-history rows predate artifact hashes. Their workbooks can
        # still be viewed, while exact-run Ask AI separately requires canonical
        # facts and a fact fingerprint.
        return True
    if not re.fullmatch(r"[0-9a-f]{64}", expected_hash):
        logger.warning(
            "Round 146: persisted workbook hash is invalid aid_digest=%s",
            _id_digest(analysis_id),
        )
        return False
    try:
        actual_hash = _r146_file_sha256(excel_path)
    except Exception as hash_error:  # noqa: BLE001 - fail closed
        logger.warning(
            "Round 146: workbook hash verification failed aid_digest=%s kind=%s",
            _id_digest(analysis_id),
            type(hash_error).__name__,
        )
        return False
    parsed_hash = str(workbook.get("workbook_sha256") or "").strip().casefold()
    verified = (
        bool(re.fullmatch(r"[0-9a-f]{64}", parsed_hash))
        and secrets.compare_digest(expected_hash, actual_hash)
        and secrets.compare_digest(actual_hash, parsed_hash)
    )
    if not verified:
        logger.warning(
            "Round 146: workbook integrity mismatch aid_digest=%s",
            _id_digest(analysis_id),
        )
    return verified


def _r146_workspace_snapshot(analysis_id: str) -> tuple[Optional[dict], int]:
    """Build a path-free decision projection for an existing run."""
    import manager_decision_workspace as decision_workspace

    status = _r146_status_for_workspace(analysis_id)
    if status is None:
        return None, 404
    excel_path = _r146_workspace_artifact(status, "excel")
    workbook = None
    workbook_warning = ""
    if excel_path:
        expected_excel_hash = _r146_persisted_excel_hash(analysis_id, status)
        try:
            workbook = decision_workspace.load_workbook_snapshot(excel_path)
            if not _r146_workbook_hash_verified(analysis_id, expected_excel_hash, excel_path, workbook):
                return None, 409
        except Exception as workbook_error:  # noqa: BLE001 - verified rows fail closed
            logger.warning(
                "Round 146: decision workbook unavailable aid_digest=%s kind=%s",
                _id_digest(analysis_id),
                type(workbook_error).__name__,
            )
            if expected_excel_hash:
                return None, 409
            workbook_warning = (
                "The Source Data workbook could not be read. Downloads remain available when the artifact is present."
            )
    snapshot = decision_workspace.snapshot_from_status(status, workbook)
    if not snapshot.get("fact_fingerprint"):
        snapshot["fact_fingerprint"] = str(status.get("fact_fingerprint") or "").strip()
    if not snapshot.get("data_as_of_utc"):
        snapshot["data_as_of_utc"] = str(status.get("data_as_of_utc") or status.get("data_retrieved_at") or "").strip()
    snapshot["word_available"] = bool(_r146_workspace_artifact(status, "word"))
    snapshot["excel_available"] = bool(excel_path)
    snapshot["workbook_loaded"] = bool(workbook)
    snapshot["downloads"] = {
        "word": url_for("download_result", analysis_id=analysis_id, file_type="docx")
        if snapshot["word_available"]
        else "",
        "source_data": url_for("download_result", analysis_id=analysis_id, file_type="xlsx")
        if snapshot["excel_available"]
        else "",
    }
    if workbook_warning:
        snapshot.setdefault("source_warnings", []).append(workbook_warning)
    # Only manager-facing warning copy crosses the API boundary. Persisted
    # partial warning dictionaries can contain internal dataset/error tokens.
    snapshot.pop("partial_data_warnings", None)
    snapshot["ask_ai_binding"] = decision_workspace.ask_ai_binding(snapshot)
    snapshot["ask_ai_url"] = (
        url_for("ask_ai_page", report_analysis_id=analysis_id)
        if snapshot.get("ask_ai_binding_available") is not False
        else ""
    )
    return snapshot, 200


@app.route("/api/decision-workspace/scope-preview", methods=["GET"])
def decision_workspace_scope_preview():
    """Round 146: explain the exact requested scope before generation."""
    import manager_decision_workspace as decision_workspace

    report_type = str(request.args.get("report_type") or "leader").strip().lower()
    scope_type = str(request.args.get("scope_type") or "team").strip().lower()
    scope_value = str(request.args.get("scope_value") or "").strip()
    member_email = str(request.args.get("member_email") or "").strip()
    subscription_id = str(request.args.get("subscription_id") or "").strip()
    try:
        selection = decision_workspace.validate_workspace_selection(
            report_type=report_type,
            manager=request.args.get("manager"),
            technology=request.args.get("technology") or "All",
            days=request.args.get("days") or 90,
            scope_type=scope_type,
            scope_value=scope_value,
            subscription_id=subscription_id,
            allowed_managers=MANAGERS,
            allowed_technologies=(
                list(TECH_CHOICES) + ["All", "All Contact Center", "Webex Contact Center Enterprise"]
            ),
        )
    except ValueError as selection_error:
        return jsonify({"ok": False, "error": str(selection_error)}), 400

    members: list[dict] = []
    customers: list[dict] = []
    source_state = "unknown"
    warning = ""
    if report_type == "leader":
        payload, status_code = _r146_leader_scope_options_payload(
            selection["manager"],
            member_email=(scope_value if scope_type == "member" else member_email),
            include_customers=scope_type == "customer",
        )
        if status_code != 200:
            return jsonify({"ok": False, "error": payload.get("error") or "Scope is unavailable."}), status_code
        members = payload.get("members") or []
        customers = payload.get("customers") or []
        warning = str(payload.get("warning") or "")
        if scope_type == "customer":
            allowed_values = {
                str(option.get("value") or "").strip() for option in customers if isinstance(option, dict)
            }
            if scope_value not in allowed_values:
                return jsonify(
                    {
                        "ok": False,
                        "error": "The selected customer is unavailable in this authorized Leader scope.",
                    }
                ), 400
            source_state = "available" if payload.get("customers_available") else "unavailable"
        else:
            source_state = "available"

    local_fixture = str(os.environ.get("ADOPTIQ_LOCAL_ACCEPTANCE_ACTIVE", "")).strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }
    preview = decision_workspace.build_scope_preview(
        selection,
        members=members,
        customers=customers,
        source_mode="local_fixture_guarded" if local_fixture else "live",
        source_state=source_state,
        warning=warning,
        data_as_of_utc=_now_utc_iso_z(),
    )
    return jsonify({"ok": True, "preview": preview})


@app.route("/api/decision-workspace/report/<analysis_id>", methods=["GET"])
def decision_workspace_report(analysis_id: str):
    snapshot, status_code = _r146_workspace_snapshot(analysis_id)
    if snapshot is None:
        error = (
            "The report Source Data integrity could not be verified."
            if status_code == 409
            else "Report run was not found."
        )
        return jsonify({"ok": False, "error": error}), status_code
    return jsonify({"ok": True, "report": snapshot})


@app.route("/api/decision-workspace/report/<analysis_id>/evidence", methods=["GET"])
def decision_workspace_report_evidence(analysis_id: str):
    """Round 147: resolve a visible report claim to exact Source Data rows."""
    import manager_decision_workspace as decision_workspace

    snapshot, status_code = _r146_workspace_snapshot(analysis_id)
    if snapshot is None:
        error = (
            "The report Source Data integrity could not be verified."
            if status_code == 409
            else "Report run was not found."
        )
        return jsonify({"ok": False, "error": error}), status_code
    if snapshot.get("evidence_available") is not True:
        return jsonify(
            {
                "ok": False,
                "error": snapshot.get("evidence_notice")
                or ("Record-level evidence is unavailable for this report. Generate a current canonical report."),
            }
        ), 409
    status = _r146_status_for_workspace(analysis_id)
    excel_path = _r146_workspace_artifact(status or {}, "excel")
    if not excel_path:
        return jsonify({"ok": False, "error": "The paired Source Data workbook is unavailable."}), 409
    expected_excel_hash = _r146_persisted_excel_hash(analysis_id, status or {})
    if not _r147_exact_artifact_hash_verified(analysis_id, expected_excel_hash, excel_path):
        return jsonify(
            {
                "ok": False,
                "error": (
                    "The report evidence does not have a valid persisted artifact "
                    "integrity proof. Regenerate the report before using this evidence."
                ),
            }
        ), 409
    evidence_key = str(request.args.get("evidence_key") or "").strip()
    try:
        limit = int(request.args.get("limit") or 25)
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "Evidence limit must be a whole number."}), 400
    try:
        evidence = decision_workspace.load_workbook_evidence(
            excel_path,
            evidence_key,
            expected_fingerprint=snapshot.get("fact_fingerprint") or "",
            limit=limit,
        )
        if not _r147_exact_artifact_hash_verified(analysis_id, expected_excel_hash, excel_path):
            raise decision_workspace.EvidenceIntegrityError(
                "The Source Data artifact changed during evidence selection."
            )
    except decision_workspace.EvidenceNotFoundError:
        return jsonify({"ok": False, "error": "Evidence was not found for this report item."}), 404
    except decision_workspace.EvidenceIntegrityError:
        logger.warning(
            "Round 147: evidence integrity failure aid_digest=%s",
            _id_digest(analysis_id),
        )
        return jsonify(
            {
                "ok": False,
                "error": "The report evidence integrity check failed. Regenerate the report before using this evidence.",
            }
        ), 409
    except ValueError as evidence_error:
        return jsonify({"ok": False, "error": str(evidence_error)}), 400
    evidence["source_data_url"] = url_for("download_result", analysis_id=analysis_id, file_type="xlsx")
    response = jsonify({"ok": True, "evidence": evidence})
    response.headers["Cache-Control"] = "no-store"
    return response


@app.route("/api/decision-workspace/history", methods=["GET"])
def decision_workspace_history():
    """Round 146: path-free, filterable report history."""
    import manager_decision_workspace as decision_workspace

    records = []
    if callable(get_report_history):
        try:
            # The admin dashboard defaults to a 50-row page, but decision
            # history must still find early Leader scope runs after a larger
            # acceptance/report matrix. The persistence helper enforces the
            # bounded upper limit.
            records = get_report_history(limit=1_000)
        except TypeError:
            # Compatibility for embedded/test adapters that still expose the
            # historical no-argument callable.
            records = get_report_history()
    filtered = decision_workspace.filter_history(
        records,
        manager=request.args.get("manager", ""),
        report_type=request.args.get("report_type", ""),
        scope_type=request.args.get("scope_type", ""),
        customer=request.args.get("customer", ""),
        technology=request.args.get("technology", ""),
        status=request.args.get("status", ""),
    )[:100]
    for item in filtered:
        analysis_id = item.get("analysis_id") or ""
        status = _r146_status_for_workspace(analysis_id)
        word_path = _r146_workspace_artifact(status, "word") if isinstance(status, dict) else None
        excel_path = _r146_workspace_artifact(status, "excel") if isinstance(status, dict) else None
        item["word_available"] = bool(word_path)
        item["excel_available"] = bool(excel_path)
        item["details_url"] = url_for("decision_workspace_report", analysis_id=analysis_id)
        item["progress_url"] = url_for("progress", analysis_id=analysis_id)
        item["word_url"] = url_for("download_result", analysis_id=analysis_id, file_type="docx") if word_path else ""
        item["source_data_url"] = (
            url_for("download_result", analysis_id=analysis_id, file_type="xlsx") if excel_path else ""
        )
    return jsonify({"ok": True, "reports": filtered, "count": len(filtered)})


@app.route("/api/decision-workspace/compare", methods=["POST"])
def decision_workspace_compare():
    """Round 146: compare canonical snapshots, never client-submitted facts."""
    import manager_decision_workspace as decision_workspace

    if app.config.get("WTF_CSRF_ENABLED", True):
        try:
            validate_csrf(request.headers.get("X-CSRFToken") or request.headers.get("X-CSRF-Token"))
        except Exception:
            return jsonify({"ok": False, "error": "CSRF validation failed"}), 403
    data = request.get_json(silent=True) or {}
    before_id = str(data.get("before_analysis_id") or "").strip()
    after_id = str(data.get("after_analysis_id") or "").strip()
    if before_id == after_id or not _is_valid_analysis_id(before_id) or not _is_valid_analysis_id(after_id):
        return jsonify({"ok": False, "error": "Select two different report runs."}), 400
    before, before_code = _r146_workspace_snapshot(before_id)
    after, after_code = _r146_workspace_snapshot(after_id)
    if before is None or after is None:
        status_code = max(before_code, after_code)
        error = (
            "One or both report Source Data artifacts could not be verified."
            if status_code == 409
            else "One or both report runs were not found."
        )
        return jsonify({"ok": False, "error": error}), status_code
    if not before.get("workbook_loaded") or not after.get("workbook_loaded"):
        return jsonify(
            {
                "ok": False,
                "error": "Both reports need a Source Data workbook before they can be compared.",
            }
        ), 409
    if before.get("canonical_snapshot") is not True or after.get("canonical_snapshot") is not True:
        return jsonify(
            {
                "ok": False,
                "error": (
                    "Both reports must use the current canonical Source Data contract. "
                    "Generate a new report for any older workbook before comparing."
                ),
            }
        ), 409
    comparison = decision_workspace.compare_snapshots(before, after)
    if comparison.get("same_scope") is not True:
        return jsonify(
            {
                "ok": False,
                "error": (
                    "Select two like-for-like reports with the same report family, "
                    "manager, technology, scope, and time window."
                ),
                "comparison": comparison,
            }
        ), 409
    comparison["before"] = {
        "analysis_id": before_id,
        "scope_label": before.get("scope_label"),
        "completed_at": before.get("completed_at"),
    }
    comparison["after"] = {
        "analysis_id": after_id,
        "scope_label": after.get("scope_label"),
        "completed_at": after.get("completed_at"),
    }
    return jsonify({"ok": True, "comparison": comparison})


