@app.route("/search_related_defects", methods=["POST"])
def search_related_defects():
    """Search for defects related to a product or issue"""
    if app.config.get("WTF_CSRF_ENABLED", True):
        try:
            validate_csrf(request.headers.get("X-CSRFToken") or request.headers.get("X-CSRF-Token"))
        except Exception:
            return jsonify(
                {"ok": False, "success": False, "error": "CSRF validation failed"}
            ), 403  # Round 13 / Phase 4.3
    try:
        data = request.get_json() or {}
        search_terms = data.get("search_terms", [])
        if isinstance(search_terms, str):
            search_terms = [s.strip() for s in search_terms.split(",") if s.strip()]
        product_filter = data.get("product_filter", None)
        try:
            days_back = int(data.get("days_back", 90))
            days_back = max(1, min(days_back, 365))
        except (ValueError, TypeError):
            days_back = 90

        if not search_terms:
            return jsonify({"error": "Please provide search terms"}), 400

        # Import and initialize integrations
        from cisco_internal_integrations import CiscoInternalIntegrations
        import os

        integrations = CiscoInternalIntegrations(
            bst_api_key=os.environ.get("BST_API_KEY"),
            psirt_api_key=os.environ.get("PSIRT_API_KEY"),
            psirt_client_secret=os.environ.get("PSIRT_CLIENT_SECRET"),
        )

        # Search for defects
        defects = integrations.search_defects_bst(
            search_terms=search_terms, product_filter=product_filter, days_back=days_back
        )

        # FIXED: Convert ALL results to serializable format
        defect_list = []
        for defect in defects:
            defect_list.append(
                {
                    "defect_id": defect.defect_id,
                    "title": defect.title,
                    "status": defect.status,
                    "severity": defect.severity,
                    "product": defect.product,
                    "created_date": defect.created_date,
                    "classification": defect.classification.value,
                    # Round 152 / A2: percent-encode the upstream identifier
                    # before it becomes a URL the browser will render as an
                    # ``href``.  ``cisco_internal_integrations`` already quotes
                    # its two ``direct_link`` builders; these two related-search
                    # payloads were the unquoted outliers.
                    "direct_link": (
                        "https://bst.cisco.com/bugsearch/bug/"
                        + _urlquote(str(defect.defect_id), safe="")
                    ),
                }
            )

        return jsonify({"success": True, "count": len(defect_list), "defects": defect_list})

    except Exception as e:
        logger.error(f"Error in search_related_defects: {e}", exc_info=True)
        return jsonify({"error": "An internal error occurred during defect search"}), 500


@app.route("/search_related_vulnerabilities", methods=["POST"])
def search_related_vulnerabilities():
    """Search for vulnerabilities related to a product or issue"""
    if app.config.get("WTF_CSRF_ENABLED", True):
        try:
            validate_csrf(request.headers.get("X-CSRFToken") or request.headers.get("X-CSRF-Token"))
        except Exception:
            return jsonify(
                {"ok": False, "success": False, "error": "CSRF validation failed"}
            ), 403  # Round 13 / Phase 4.3
    try:
        data = request.get_json() or {}
        search_terms = data.get("search_terms", [])
        if isinstance(search_terms, str):
            search_terms = [s.strip() for s in search_terms.split(",") if s.strip()]
        product_filter = data.get("product_filter", None)
        try:
            days_back = int(data.get("days_back", 90))
            days_back = max(1, min(days_back, 365))
        except (ValueError, TypeError):
            days_back = 90

        if not search_terms:
            return jsonify({"error": "Please provide search terms"}), 400

        # Import and initialize integrations
        from cisco_internal_integrations import CiscoInternalIntegrations
        import os

        integrations = CiscoInternalIntegrations(
            bst_api_key=os.environ.get("BST_API_KEY"),
            psirt_api_key=os.environ.get("PSIRT_API_KEY"),
            psirt_client_secret=os.environ.get("PSIRT_CLIENT_SECRET"),
        )

        # Search for vulnerabilities
        vulnerabilities = integrations.search_psirt_vulnerabilities(
            search_terms=search_terms, product_filter=product_filter, days_back=days_back
        )

        # FIXED: Convert ALL results to serializable format
        vuln_list = []
        for vuln in vulnerabilities:
            vuln_list.append(
                {
                    "advisory_id": vuln.advisory_id,
                    "title": vuln.title,
                    "severity": vuln.severity,
                    "cve_ids": vuln.cve_ids,  # Show ALL CVEs
                    "bug_ids": vuln.bug_ids,  # Show ALL bug IDs
                    "products": vuln.products,  # Show ALL products
                    "published_date": vuln.published_date,
                    "classification": vuln.classification.value,
                    # Round 152 / A2: see the BST sibling above.
                    "direct_link": (
                        "https://tools.cisco.com/security/center/content/CiscoSecurityAdvisory/"
                        + _urlquote(str(vuln.advisory_id), safe="")
                    ),
                }
            )

        return jsonify({"success": True, "count": len(vuln_list), "vulnerabilities": vuln_list})

    except Exception as e:
        logger.error(f"Error in search_related_vulnerabilities: {e}", exc_info=True)
        return jsonify({"error": "An internal error occurred during vulnerability search"}), 500


def _check_port_available(port):
    """Return (available: bool, pid: int|None, process_name: str|None)."""
    import socket
    import subprocess

    # Round 8 / Phase 1.12: defence-in-depth -- clamp port to the legal
    # TCP range before passing it to ``socket.bind`` and ``lsof -i :%s``.
    # No untrusted call site exists today, but if one ever appeared a
    # negative or 70000+ value would either raise from socket directly
    # (OK) or, in the lsof fallback, end up as ``-i :-1`` / ``-i :70000``
    # which lsof interprets unpredictably.  Reject early with the same
    # ``(False, None, None)`` signal the caller already handles for an
    # in-use port.
    try:
        port_int = int(port)
    except (TypeError, ValueError):
        return (False, None, None)
    if not (0 <= port_int <= 65535):
        return (False, None, None)
    port = port_int
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        s.bind(("", port))
        s.close()
        return (True, None, None)
    except OSError:
        s.close()
    pid, name = None, None
    try:
        import psutil

        for conn in psutil.net_connections(kind="tcp"):
            if getattr(conn, "laddr", None) and getattr(conn.laddr, "port", None) == port:
                if getattr(conn, "pid", None):
                    pid = conn.pid
                    try:
                        name = psutil.Process(pid).name()
                    except (psutil.NoSuchProcess, psutil.AccessDenied):
                        name = "(PID %s)" % pid
                    break
    except (ImportError, psutil.AccessDenied, AttributeError):
        pass
    # Fallback: on macOS psutil may not return the listener PID; use lsof
    if pid is None and sys.platform == "darwin":
        try:
            out = subprocess.check_output(
                ["lsof", "-i", ":%s" % port, "-t"], stderr=subprocess.DEVNULL, text=True, timeout=5
            )
            pids = [int(x) for x in out.strip().split() if x.strip()]
            if pids:
                pid = pids[0]
                try:
                    name = psutil.Process(pid).name()
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    name = "(PID %s)" % pid
        except (subprocess.CalledProcessError, subprocess.TimeoutExpired, ValueError, FileNotFoundError):
            pass
    return (False, pid, name)


def _probe_existing_adoptiq(port, timeout=2.0):
    """Best-effort check whether the TCP listener on ``port`` is another
    live AdoptIQ instance (vs. an unrelated process happening to hold the
    same port).

    Round 38.1 / Build13: when the user double-clicks the .app while an
    instance is already running, the prior behaviour was to show an
    osascript dialog ("Quit it and start this one?") that opened *behind*
    other windows.  After a 15s osascript timeout the new process called
    ``sys.exit(0)`` silently, so the user perceived the .app as having
    "bounced for a few minutes then stopped".

    The correct UX is: when an existing AdoptIQ is detected on the port,
    skip the dialog entirely and just re-focus the browser to the
    existing instance.  This helper returns ``True`` only when an HTTP
    probe of ``http://127.0.0.1:<port>/`` succeeds AND the body contains
    an AdoptIQ marker, so we never mistake an unrelated server (e.g.
    ``Duo Desktop`` or a stray Werkzeug from another project) for our
    own.

    The probe is best-effort (short timeout, errors swallowed) because
    the duplicate-launch path must remain fast and never block boot.
    """
    try:
        port_int = int(port)
    except (TypeError, ValueError):
        return False
    if not (1 <= port_int <= 65535):
        return False
    try:
        import urllib.request as _urlreq
    except ImportError:  # pragma: no cover - stdlib always present
        return False
    try:
        # Round 38.1: ruff S310 ignored intentionally. The URL is built
        # from a literal http:// scheme + 127.0.0.1 host + an int that
        # we validated above to be in 1..65535. There is no user-supplied
        # scheme, host, or path that could escape to file://, gopher://,
        # or off-box; the probe is deliberately loopback-only.
        with _urlreq.urlopen(  # noqa: S310  # nosec B310
            "http://127.0.0.1:%d/" % port_int, timeout=timeout
        ) as resp:
            body = resp.read(4096).decode("utf-8", errors="ignore").lower()
    except Exception:
        return False
    return "adoptiq" in body


# Round 87 / Phase 3: launcher auto-quit-stale helpers.
#
# Pre-R87 the duplicate-launch branch routed the user back to the
# already-running instance via R38.1's webbrowser.open + sys.exit(0).
# That was correct for "user double-clicked twice in 10 seconds" but
# wrong for "user installed Build N+1 and double-clicked from
# /Applications while Build N is still on port 5151" -- they got
# routed to the OLD build with a "Restart required" banner that
# required them to manually quit and relaunch.  Round 87 detects the
# stale-binary case and force-quits the older instance so the new
# build can boot in its place.
#
# The detection chain is intentionally narrow:
#   * Frozen-only (``sys.frozen`` truthy).  Dev iteration must be
#     predictable; never auto-kill a `python app_simple.py` running in
#     a terminal session.
#   * Compares the running instance's ``process_started_at_utc``
#     (from its own ``GET /api/version``) against the freshly-launched
#     binary's ``Path(sys.executable).stat().st_mtime``.  We are stale
#     iff our mtime is unambiguously NEWER (1.0 s tolerance for
#     filesystem-mtime resolution + clock drift).
#   * Any failure -- bad port, version probe timeout, malformed JSON,
#     unparseable timestamp -- returns False so we fall back to the
#     R38.1 re-route.  Never raises into the boot path.
#
# The kill itself is ``os.kill(pid, SIGTERM)`` not the HTTP
# ``/api/shutdown`` endpoint.  The HTTP path requires either CSRF
# (browser-only) or the ``ADOPTIQ_INTERNAL_TOKEN`` env var matching
# between processes -- the new launcher process can't share that
# token cleanly with the running one without a sidecar pidfile + key
# scheme.  SIGTERM still fires the ``atexit`` handlers in the running
# process (``_shutdown_handler`` saves analysis_status, ``_r17_corpus_shutdown``
# scrubs the corpus temp file), so the cleanup contract is preserved.


def _query_running_instance_started_at(port, timeout=2.0):
    """Round 87 / Phase 3: return the running instance's ``process_started_at_utc``.

    GETs ``http://127.0.0.1:<port>/api/version`` and pulls the
    ``process_started_at_utc`` ISO timestamp out of the JSON.
    Best-effort: returns ``None`` on any error (malformed port,
    network timeout, JSON parse failure, missing field).  Never
    raises into the boot path.
    """
    try:
        port_int = int(port)
    except (TypeError, ValueError):
        return None
    if not (1 <= port_int <= 65535):
        return None
    try:
        import json as _r87_json
        import urllib.request as _r87_urlreq
    except ImportError:  # pragma: no cover - stdlib always present
        return None
    try:
        # Round 87: same loopback-only safety as _probe_existing_adoptiq.
        # URL built from http:// + 127.0.0.1 + validated int port.
        with _r87_urlreq.urlopen(  # noqa: S310  # nosec B310
            "http://127.0.0.1:%d/api/version" % port_int, timeout=timeout
        ) as resp:
            payload = _r87_json.loads(resp.read(8192).decode("utf-8", errors="ignore"))
    except Exception:
        return None
    if not isinstance(payload, dict):
        return None
    started = payload.get("process_started_at_utc")
    if not started:
        return None
    return str(started)


def _running_instance_is_stale(port, our_mtime, *, timeout=2.0):
    """Round 87 / Phase 3: True iff the running instance is older than us.

    ``our_mtime`` is typically ``Path(sys.executable).stat().st_mtime``
    captured fresh at boot (the freshly-double-clicked .app's binary).
    ``port`` is the main TCP port the running instance is bound to.

    Returns False (preserve R38.1 re-route) when:
      * not running in a frozen build (dev iteration must be predictable)
      * the running instance's ``/api/version`` is unreachable, malformed,
        or the ``process_started_at_utc`` field is unparseable
      * the running instance's started-at is >= our mtime (the running
        binary IS our binary -- still a duplicate launch, just not stale)

    Returns True only when the new install is unambiguously newer
    than the running process's start time.  1.0 s tolerance avoids
    clock-drift and filesystem-mtime-resolution false positives.
    """
    if not getattr(sys, "frozen", False):
        return False
    started_iso = _query_running_instance_started_at(port, timeout=timeout)
    if not started_iso:
        return False
    try:
        from datetime import datetime as _r87_dt, timezone as _r87_tz

        # ``datetime.fromisoformat`` in 3.11 accepts +HH:MM offsets but
        # not the Zulu shorthand 'Z'.  Normalise so the parser doesn't
        # raise on payloads that use either form.
        normalised = started_iso.strip()
        if normalised.endswith("Z"):
            normalised = normalised[:-1] + "+00:00"
        started_dt = _r87_dt.fromisoformat(normalised)
        if started_dt.tzinfo is None:
            started_dt = started_dt.replace(tzinfo=_r87_tz.utc)
        started_epoch = started_dt.timestamp()
    except Exception:
        return False
    try:
        our_epoch = float(our_mtime)
    except (TypeError, ValueError):
        return False
    # Strict newer-than.  1.0 s tolerance covers HFS+ / APFS mtime
    # resolution + small clock skew between the build host and the
    # user's machine.
    return our_epoch > started_epoch + 1.0


def _force_quit_existing_adoptiq(port, *, pid=None, timeout=10.0, poll_interval=0.5):
    """Round 87 / Phase 3: SIGTERM a stale running AdoptIQ on ``port``.

    Resolves the listener pid via ``_check_port_available`` if not
    supplied, sends ``SIGTERM`` (NOT SIGKILL -- atexit handlers must
    fire so analysis_status saves and the corpus temp file gets
    scrubbed), then polls ``_check_port_available`` until the port
    frees up or ``timeout`` elapses.

    Returns True on success (port free), False on timeout or kill
    failure.  Never raises -- the caller is the boot path and a
    failure must fall back to the R38.1 re-route, not crash.
    """
    import signal as _r87_signal
    import time as _r87_time

    if pid is None:
        try:
            _, found_pid, _ = _check_port_available(port)
            pid = found_pid
        except Exception:
            return False
    if not pid:
        return False
    try:
        pid_int = int(pid)
    except (TypeError, ValueError):
        return False

    try:
        os.kill(pid_int, _r87_signal.SIGTERM)
    except (OSError, ProcessLookupError, PermissionError) as kill_err:
        logger.debug(
            "Round 87 / force-quit: kill(%s, SIGTERM) failed: %s",
            pid_int,
            kill_err,
        )
        return False

    deadline = _r87_time.monotonic() + max(0.5, float(timeout))
    while _r87_time.monotonic() < deadline:
        try:
            available, _, _ = _check_port_available(port)
            if available:
                return True
        except Exception:  # pragma: no cover - defensive
            pass
        _r87_time.sleep(poll_interval)
    return False


# Round 97: TACTrack-style startup splash helpers.  These are intentionally
# separate from the R87 duplicate/stale-instance helpers above: the splash only
# improves first-launch feedback, while R87 continues to own process safety.
def _open_browser_url(url: str) -> bool:
    """Best-effort browser handoff for AdoptIQ's local web UI."""
    target = str(url or "").strip()
    if not target:
        return False
    try:
        if sys.platform == "darwin":
            # Round 97: fixed executable with structured args; no shell.
            subprocess.Popen(  # noqa: S603  # nosec B603
                ["/usr/bin/open", target],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            return True
        return bool(webbrowser.open(target))
    except Exception as open_err:  # noqa: BLE001 - startup UX best effort
        logger.debug("_open_browser_url failed for %r: %s", target, open_err)
        return False


def _launcher_splash_already_shown(environ=None) -> bool:
    """Return True when the macOS bundle launcher already opened the splash."""
    env = os.environ if environ is None else environ
    marker = str(env.get("ADOPTIQ_LAUNCHER_SPLASH_SHOWN") or "").strip().lower()
    return marker in {"1", "true", "yes", "on"}


def _startup_splash_html(port: int) -> str:
    """Return the local startup splash page shown before Flask is ready."""
    app_url = f"http://localhost:{port}/"
    ping_url = f"http://localhost:{port}/ping"
    return f"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>AdoptIQ is starting</title>
  <style>
    :root {{
      color-scheme: light dark;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }}
    body {{
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      background: #06172b;
      color: #ffffff;
    }}
    main {{
      max-width: 34rem;
      padding: 2rem;
      text-align: center;
    }}
    .spinner {{
      width: 2.75rem;
      height: 2.75rem;
      margin: 0 auto 1.25rem;
      border: 0.3rem solid rgba(255,255,255,0.3);
      border-top-color: #35c7ff;
      border-radius: 50%;
      animation: spin 1s linear infinite;
    }}
    @keyframes spin {{
      to {{ transform: rotate(360deg); }}
    }}
    p {{
      color: #d7dde8;
      line-height: 1.45;
    }}
    a {{
      color: #35c7ff;
    }}
  </style>
</head>
<body>
  <main>
    <div class="spinner" aria-hidden="true"></div>
    <h1>AdoptIQ is starting...</h1>
    <p>Your browser will open AdoptIQ automatically when it is ready.</p>
    <p>Reports remain safe to run while the knowledge corpus indexes in the background.</p>
    <p>If this page does not redirect, <a href="{app_url}">open AdoptIQ</a>.</p>
  </main>
  <script>
    const appUrl = "{app_url}";
    const pingUrl = "{ping_url}";
    async function waitForAdoptIQ() {{
      try {{
        const response = await fetch(pingUrl, {{ cache: "no-store" }});
        if (!response.ok) {{ throw new Error("status " + response.status); }}
        const body = await response.text();
        if (body.trim() !== "OK") {{ throw new Error("unexpected ping body"); }}
        window.location.replace(appUrl);
      }} catch (error) {{
        window.setTimeout(waitForAdoptIQ, 1000);
      }}
    }}
    waitForAdoptIQ();
  </script>
</body>
</html>
"""


def _open_startup_splash(port: int) -> bool:
    """Open a local browser splash page while frozen macOS startup completes."""
    try:
        port_int = int(port)
    except (TypeError, ValueError):
        return False
    if port_int < 1 or port_int > 65535:
        return False
    if sys.platform != "darwin" or not getattr(sys, "frozen", False):
        return False

    try:
        with tempfile.NamedTemporaryFile(
            "w",
            suffix=".html",
            prefix="adoptiq-starting-",
            delete=False,
            encoding="utf-8",
        ) as splash_file:
            splash_file.write(_startup_splash_html(port_int))
            splash_path = splash_file.name
        # Round 97: fixed executable with structured args; no shell.
        subprocess.Popen(  # noqa: S603  # nosec B603
            ["/usr/bin/open", splash_path],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
        return True
    except Exception as splash_err:  # noqa: BLE001 - startup UX best effort
        logger.debug("_open_startup_splash failed; continuing: %s", splash_err)
        return False


# Round 17.3: resolve the main-app TCP port from the environment so
# operators can move AdoptIQ off a contested port without a rebuild.
# 5151 is adjacent to the user's other 5150 ("Van Halen") app and out
# of the macOS AirPlay Receiver / Flask-default 5000-5001 conflict zone.
_DEFAULT_MAIN_PORT = 5151


def _resolve_main_port(env=None):
    """Return the main-app TCP port from ``ADOPTIQ_PORT`` or the default.

    Out-of-range or non-integer values fall back to the default with a
    warning log.  Pulled out as a tiny helper so the test surface is
    a single function rather than the ``if __name__ == "__main__"``
    block.
    """
    env_map = os.environ if env is None else env
    raw = (env_map.get("ADOPTIQ_PORT") or "").strip()
    if not raw:
        return _DEFAULT_MAIN_PORT
    try:
        candidate = int(raw)
    except (TypeError, ValueError):
        logger.warning(
            "ADOPTIQ_PORT=%r is not an integer; falling back to %d",
            raw,
            _DEFAULT_MAIN_PORT,
        )
        return _DEFAULT_MAIN_PORT
    if not (1 <= candidate <= 65535):
        logger.warning(
            "ADOPTIQ_PORT=%d is outside the 1-65535 TCP range; falling back to %d",
            candidate,
            _DEFAULT_MAIN_PORT,
        )
        return _DEFAULT_MAIN_PORT
    return candidate


def _shutdown_handler():
    """Save analysis status on shutdown.

    Round 14 / Phase 3.1: previously this function called
    ``logger.info`` and ``logger.error`` unconditionally.  ``atexit``
    handlers run after pytest's capture plugin (and many production
    container runtimes) have already closed the underlying
    ``StreamHandler`` streams, so the unguarded log calls produced
    ``ValueError: I/O operation on closed file`` at the end of every
    pytest run and -- more importantly -- after every clean shutdown
    of the desktop bundle.  The ``ValueError`` is swallowed inside
    ``logging.Handler.handleError``; the visible side-effect is a
    ``--- Logging error ---`` diagnostic printed to stderr.  Toggle
    ``logging.raiseExceptions`` off for the duration of the shutdown
    log emission so that diagnostic stays out of stdout/stderr while
    the rest of the handler runs unchanged.
    """
    try:
        save_analysis_status()
    except Exception as save_err:
        _prev_raise = logging.raiseExceptions
        logging.raiseExceptions = False
        try:
            try:
                logger.error("Failed to save status on shutdown: %s", save_err)
            except Exception:
                pass
        finally:
            logging.raiseExceptions = _prev_raise
        return

    _prev_raise = logging.raiseExceptions
    logging.raiseExceptions = False
    try:
        try:
            logger.info("Analysis status saved on shutdown")
        except Exception:
            pass
    finally:
        logging.raiseExceptions = _prev_raise


atexit.register(_shutdown_handler)


# Round 17 / Phase B.4: gracefully shut down the corpus bootstrap so
# the in-memory plaintext temp file is scrubbed before the process
# exits.  The hook is best-effort and never raises.
def _r17_corpus_shutdown() -> None:
    try:
        import corpus_bootstrap as _r17_cb_shutdown

        _r17_cb_shutdown.stop()
    except Exception:  # noqa: BLE001 - shutdown path
        pass


atexit.register(_r17_corpus_shutdown)


if __name__ == "__main__":
    # Round 7 / Phase 3.12: incident_storage no longer initialises its
    # SQLite database as a module-level side effect.  Bootstrap the
    # schema explicitly here so the first browser request doesn't race
    # with table creation.
    try:
        from incident_storage import init_db as _incident_init_db

        _incident_init_db()
    except Exception as _init_err:  # pragma: no cover - defensive only
        import logging as _logging

        _logging.getLogger(__name__).warning(
            "Round 7 / Phase 3.12: explicit incident_storage.init_db() at bootstrap raised: %s",
            _init_err,
        )
    # Round 17.3: env-overridable port (default 5151, was 5001).  See
    # ``_resolve_main_port`` above for parsing rules.
    PORT = _resolve_main_port()
    print("AdoptIQ Simple - AI-Powered Executive Analytics")
    print(version_string())
    print("Using EXACT CircuIT AI logic from your working script")
    print("Generating comprehensive AI-powered reports")
    print("Access at: http://localhost:%s/" % PORT)

    available, other_pid, other_name = _check_port_available(PORT)
    if not available:
        # Round 38.1 / Build13: short-circuit when the listener IS already
        # AdoptIQ.  The previous flow blocked on an osascript dialog that
        # opened behind other windows, then silently exited after 15s,
        # producing the "bounced for a few minutes then stopped" symptom
        # the user reported.  When we can prove the existing process is
        # an AdoptIQ instance, just re-focus the browser there and exit
        # cleanly -- no dialog, no Dock-bounce-into-the-void.
        if _probe_existing_adoptiq(PORT):
            # Round 87 / Phase 3: when we are launching a NEWER frozen
            # binary than the already-running instance, force-quit the
            # stale process and boot fresh.  Pre-R87 the user had to
            # manually quit + relaunch because the R38.1 re-route
            # silently routed them to the old build with a "Restart
            # required" banner.  We now do that for them.
            _r87_our_mtime = None
            if getattr(sys, "frozen", False):
                try:
                    _r87_our_mtime = Path(sys.executable).stat().st_mtime
                except OSError as _r87_stat_err:
                    logger.debug(
                        "Round 87: stat(sys.executable) failed: %s",
                        _r87_stat_err,
                    )
                    _r87_our_mtime = None
            _r87_should_force_quit = _r87_our_mtime is not None and _running_instance_is_stale(PORT, _r87_our_mtime)
            if _r87_should_force_quit:
                print("AdoptIQ: stale older instance detected on port %s; shutting it down and starting fresh." % PORT)
                if _force_quit_existing_adoptiq(PORT, pid=other_pid):
                    print("AdoptIQ: stale instance shut down; continuing boot.")
                    # Re-check port availability so the rest of the
                    # ``if not available:`` block (the in-use dialog
                    # logic) is short-circuited.  Mirrors the kill-then-
                    # recheck pattern at lines ~28954 and ~28999 in the
                    # existing macOS / CLI dialog flows.
                    available, other_pid, other_name = _check_port_available(PORT)
                    if not available:
                        print(
                            "AdoptIQ: port %s did not free after "
                            "force-quit; re-routing to localhost as a "
                            "fallback." % PORT
                        )
                        _open_browser_url("http://localhost:%s/" % PORT)
                        sys.exit(0)
                    # Fall through to normal boot below; ``available``
                    # is now True so the in-use dialog block is skipped.
                else:
                    print("AdoptIQ: could not force-quit stale instance; falling back to re-route.")
                    _open_browser_url("http://localhost:%s/" % PORT)
                    sys.exit(0)
            else:
                # Not frozen, not stale, or version probe failed --
                # preserve R38.1 / Build13 re-route to existing instance.
                print("AdoptIQ is already running on http://localhost:%s/ -- opening that instance." % PORT)
                _open_browser_url("http://localhost:%s/" % PORT)
                sys.exit(0)

    # Round 87 / Phase 3: the in-use dialog logic only runs when the
    # listener is NOT AdoptIQ at all (probe returned False) or the R87
    # force-quit path bailed without sys.exit (impossible; all failure
    # branches above sys.exit).  Wrap in another ``if not available:``
    # so the post-force-quit success path skips the dialog cleanly --
    # ``available`` was just re-set to True.
    if not available:
        print("")
        print("Port %s is in use by another program." % PORT)
        if other_pid and other_name:
            print("  Process: %s (PID %s)" % (other_name, other_pid))
        if sys.platform == "win32":
            print("  Either stop that program or run: taskkill /PID <PID> /F")
        else:
            print("  Either stop that program or run: lsof -i :%s  then  kill <PID>" % PORT)
        print("")

        # Packaged Mac: native dialog so user can choose to quit the other instance
        if getattr(sys, "frozen", False) and sys.platform == "darwin":
            import subprocess as _sub

            # Round 38.1 / Build13: ``tell application "System Events" to
            # activate`` brings the dialog window to the foreground so
            # the user actually sees it.  Without this prefix the dialog
            # opens behind whatever app the user was using and they
            # report the .app as "broken" because they never see the
            # prompt.  The probe above already handles the
            # AdoptIQ-vs-AdoptIQ case; this defence is for the rare
            # "some non-AdoptIQ process is on 5151" path.
            _dialog = (
                'display dialog "Port %s is in use (another AdoptIQ may be running). '
                'Quit it and start this one?" with title "AdoptIQ" '
                'buttons {"Cancel", "Quit other & start"} default button 2' % PORT
            )
            try:
                _r = _sub.run(
                    [
                        "osascript",
                        "-e",
                        'tell application "System Events" to activate',
                        "-e",
                        _dialog,
                    ],
                    capture_output=True,
                    text=True,
                    timeout=15,
                )
            except Exception:
                _r = None
            if _r and _r.returncode == 0 and "Quit other & start" in (_r.stdout or ""):
                killed = False
                if other_pid:
                    try:
                        import psutil

                        p = psutil.Process(other_pid)
                        p.terminate()
                        p.wait(timeout=3)
                        killed = True
                    except Exception as e:
                        print("  Could not stop the process: %s" % e)
                if not killed and sys.platform == "darwin":
                    try:
                        out = _sub.check_output(
                            ["lsof", "-i", ":%s" % PORT, "-t"], stderr=_sub.DEVNULL, text=True, timeout=5
                        )
                        for pid_str in out.strip().split():
                            try:
                                pid = int(pid_str)
                                _sub.run(["kill", str(pid)], check=False, timeout=2, capture_output=True)
                                killed = True
                            except (ValueError, _sub.TimeoutExpired):
                                pass
                    except (_sub.CalledProcessError, _sub.TimeoutExpired, FileNotFoundError):
                        pass
                if killed:
                    time.sleep(1)
                    available, _, _ = _check_port_available(PORT)
                    if not available:
                        print("  Port still in use. Please close the other application and run AdoptIQ again.")
                        sys.exit(1)
                else:
                    print(
                        "  Could not find or kill the process using the port. Try: lsof -i :%s  then  kill <PID>" % PORT
                    )
                    sys.exit(1)
            else:
                sys.exit(0)

        elif sys.stdin.isatty():
            try:
                choice = input("Kill the process using the port and start AdoptIQ? (y/n): ").strip().lower()
            except (EOFError, KeyboardInterrupt):
                choice = "n"
            if choice == "y":
                killed = False
                if other_pid:
                    try:
                        import psutil

                        p = psutil.Process(other_pid)
                        p.terminate()
                        p.wait(timeout=3)
                        killed = True
                    except Exception as e:
                        print("  Could not stop the process: %s" % e)
                if not killed and sys.platform == "darwin":
                    try:
                        import subprocess

                        out = subprocess.check_output(
                            ["lsof", "-i", ":%s" % PORT, "-t"], stderr=subprocess.DEVNULL, text=True, timeout=5
                        )
                        for pid_str in out.strip().split():
                            try:
                                pid = int(pid_str)
                                subprocess.run(["kill", str(pid)], check=False, timeout=2, capture_output=True)
                                killed = True
                            except (ValueError, subprocess.TimeoutExpired):
                                pass
                    except (subprocess.CalledProcessError, subprocess.TimeoutExpired, FileNotFoundError):
                        pass
                if killed:
                    time.sleep(1)
                    available, _, _ = _check_port_available(PORT)
                    if not available:
                        print("  Port still in use. Please close the other application and run AdoptIQ again.")
                        sys.exit(1)
                else:
                    if sys.platform == "win32":
                        print("  Could not find or kill the process. Try: taskkill /PID %s /F" % (other_pid or "<PID>"))
                    else:
                        print(
                            "  Could not find or kill the process using the port. Try: lsof -i :%s  then  kill <PID>"
                            % PORT
                        )
                    sys.exit(1)
            else:
                print("Exiting.")
                sys.exit(0)
        else:
            print("Run AdoptIQ from Command Prompt (or Terminal) to choose: kill the process or quit.")
            sys.exit(1)

    launcher_splash_shown = _launcher_splash_already_shown()
    if not launcher_splash_shown:
        _open_startup_splash(PORT)

        # Launch browser after server starts (like Mac version).  Round 97:
        # when the app-bundle launcher already opened the polling splash, this
        # direct opener is suppressed so users do not get a duplicate tab.
        def _open_browser():
            time.sleep(BROWSER_LAUNCH_DELAY_SECONDS)  # Give server time to bind
            _open_browser_url("http://localhost:%s/" % PORT)

        threading.Thread(target=_open_browser, daemon=True).start()

    # Round 8 / Phase 1.13: bind-address sanity check.  ``_SENSITIVE_ENDPOINTS``
    # is gated by ``_is_local_client`` (loopback only), but if the bind host
    # is non-loopback the entire sensitive surface (download_result,
    # cancel_analysis, intel export/import, status JSON, etc.) is exposed
    # to anyone who can reach the host on PORT.  ``ADOPTIQ_BIND_HOST`` lets
    # operators override (e.g. ``127.0.0.1`` for the desktop bundle), and
    # we hard-warn at boot when the chosen host is non-loopback while the
    # sensitive surface is enabled, so the misconfiguration is impossible
    # to miss in stdout / shipped logs.
    # Round 14 / Phase 1.1: default to loopback-only.  Previously the
    # default was ``0.0.0.0`` (any interface) with a runtime warning when
    # sensitive endpoints were registered.  That warning is easy to miss
    # in shipped desktop logs and the only reason ``0.0.0.0`` was ever
    # the default is parity with `flask run` -- not a deliberate security
    # decision.  The admin dashboard already defaults to ``127.0.0.1``
    # and gates public binding behind ``ADOPTIQ_ADMIN_BIND_PUBLIC=1``;
    # mirror that here.  Operators who *want* LAN access can either set
    # ``ADOPTIQ_BIND_HOST`` directly or flip ``ADOPTIQ_BIND_PUBLIC=1``.
    _bind_host_env = os.environ.get("ADOPTIQ_BIND_HOST", "").strip()
    if _bind_host_env:
        _bind_host = _bind_host_env
    else:
        _bind_public = os.environ.get("ADOPTIQ_BIND_PUBLIC", "").strip().lower() in {"1", "true", "yes"}
        _bind_host = "0.0.0.0" if _bind_public else "127.0.0.1"  # noqa: S104 # nosec B104 - opt-in via ADOPTIQ_BIND_PUBLIC=1
    _loopback_hosts = {"127.0.0.1", "::1", "localhost"}
    # Round 148: the integration plan requires public transport to fail
    # closed. The default loopback HTTP desktop flow remains unchanged, while
    # a public bind must declare HTTPS or explicitly opt into Secure cookies.
    try:
        require_secure_public_bind(
            _bind_host,
            os.environ.get("ADOPTIQ_MAIN_URL", "http://localhost:5151"),
            bool(app.config.get("SESSION_COOKIE_SECURE")),
        )
    except PublicBindSecurityError as _public_bind_error:
        logger.critical("[[BIND-ERROR]] %s", _public_bind_error)
        print(f"[[BIND-ERROR]] {_public_bind_error}")
        sys.exit(2)
    if _bind_host not in _loopback_hosts and _SENSITIVE_ENDPOINTS:
        _msg = (
            "[[BIND-WARNING]] AdoptIQ is binding %s while %d sensitive endpoints "
            "rely on loopback-only protection. Set ADOPTIQ_BIND_HOST=127.0.0.1 "
            "for desktop deployments, or front the app with a reverse proxy "
            "that strips/normalises X-Forwarded-For before exposing publicly."
        ) % (_bind_host, len(_SENSITIVE_ENDPOINTS))
        print(_msg)
        try:
            logger.warning(_msg)
        except Exception:
            pass
    # Round 32 / Phase 2.D: spawn the Admin Console (Flask app at
    # enhanced_admin_dashboard_v2.admin_app) in a background daemon
    # thread so the .app actually exposes http://127.0.0.1:5152/
    # without requiring the user to launch a second process.  Build6
    # bundled the admin module via PyInstaller hidden_imports but
    # never started the server -- which is why the user reported
    # "I tried going to the admin site and don't see it".  The helper
    # short-circuits in tests and quietly logs (without aborting the
    # main app) on OSError / port-in-use.
    try:
        _start_admin_server_in_thread()
    except Exception:
        logger.exception("Round 32 / Phase 2.D: admin auto-start raised; main app continuing")
    # Round 119 / Build 88: spawn the cross-platform auto-update worker.
    # No-op under pytest; idempotent; degrades to notify on any failure.
    try:
        start_update_check_worker()
    except Exception:
        logger.exception("Round 119 / Build 88: update-check worker start raised; main app continuing")
    # Round 101: explicit threaded server so slow report downloads or browser
    # keep-alive sockets cannot starve /status and /ping during live soaks.
    app.run(debug=False, host=_bind_host, port=PORT, use_reloader=False, threaded=True)
